-- 合成獸零件 v2：9 個部位 × 9 種造型，共 81 個
-- 要改零件請改 scripts/parts/parts.py，再執行一次輸出這個檔
-- 可以重複執行：先依 name UPDATE，沒有這個名字才 INSERT，不會 DELETE（user_parts 有外鍵）
-- 要先跑過 add-part-slots.sql
SET NAMES utf8mb4;
USE bug_clinic;

-- body：圓滾滾
UPDATE parts SET category = 'css', slot = 'body', price = 25, starter_code = '{"html": "", "css": "/* 想換顏色、移位置，改這裡就好 */\\n/* 圓的上下比較窄：角往下、腳往上，翅膀往內靠，才不會跟身體分開 */\\n.body {\\n  --horn-y: 7%;\\n  --leg-y: 93%;\\n  --neck-y: 72%;\\n  --wing-x: 5px;\\n  /* 圓角看不到，但點身體的範圍會跟著變圓 */\\n  border-radius: 50%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* .body 只當透明的容器，看得到的身體畫在後面兩層，零件就不會被剪掉 */\\n/* background-clip: text 讓 .body 的底色只畫在文字裡，.body 沒有文字就看不到；::after 用 background: inherit 拿到同一個底色 */\\n/* 左邊、上面的點從左上角量；右邊、下面的點用 calc(100% - ...) 從右下角量，身體變寬變高時形狀跟著撐開 */\\n.body {\\n  border-color: transparent;\\n  -webkit-background-clip: text;\\n  background-clip: text;\\n  --body-outer: polygon(\\n    48px 0,\\n    calc(100% - 48px) 0,\\n    calc(100% - 48px) 4px,\\n    calc(100% - 36px) 4px,\\n    calc(100% - 36px) 8px,\\n    calc(100% - 28px) 8px,\\n    calc(100% - 28px) 12px,\\n    calc(100% - 20px) 12px,\\n    calc(100% - 20px) 16px,\\n    calc(100% - 16px) 16px,\\n    calc(100% - 16px) 20px,\\n    calc(100% - 12px) 20px,\\n    calc(100% - 12px) 24px,\\n    calc(100% - 8px) 24px,\\n    calc(100% - 8px) 32px,\\n    calc(100% - 4px) 32px,\\n    calc(100% - 4px) 40px,\\n    100% 40px,\\n    100% calc(100% - 40px),\\n    calc(100% - 4px) calc(100% - 40px),\\n    calc(100% - 4px) calc(100% - 32px),\\n    calc(100% - 8px) calc(100% - 32px),\\n    calc(100% - 8px) calc(100% - 24px),\\n    calc(100% - 12px) calc(100% - 24px),\\n    calc(100% - 12px) calc(100% - 20px),\\n    calc(100% - 16px) calc(100% - 20px),\\n    calc(100% - 16px) calc(100% - 16px),\\n    calc(100% - 20px) calc(100% - 16px),\\n    calc(100% - 20px) calc(100% - 12px),\\n    calc(100% - 28px) calc(100% - 12px),\\n    calc(100% - 28px) calc(100% - 8px),\\n    calc(100% - 36px) calc(100% - 8px),\\n    calc(100% - 36px) calc(100% - 4px),\\n    calc(100% - 48px) calc(100% - 4px),\\n    calc(100% - 48px) 100%,\\n    48px 100%,\\n    48px calc(100% - 4px),\\n    36px calc(100% - 4px),\\n    36px calc(100% - 8px),\\n    28px calc(100% - 8px),\\n    28px calc(100% - 12px),\\n    20px calc(100% - 12px),\\n    20px calc(100% - 16px),\\n    16px calc(100% - 16px),\\n    16px calc(100% - 20px),\\n    12px calc(100% - 20px),\\n    12px calc(100% - 24px),\\n    8px calc(100% - 24px),\\n    8px calc(100% - 32px),\\n    4px calc(100% - 32px),\\n    4px calc(100% - 40px),\\n    0 calc(100% - 40px),\\n    0 40px,\\n    4px 40px,\\n    4px 32px,\\n    8px 32px,\\n    8px 24px,\\n    12px 24px,\\n    12px 20px,\\n    16px 20px,\\n    16px 16px,\\n    20px 16px,\\n    20px 12px,\\n    28px 12px,\\n    28px 8px,\\n    36px 8px,\\n    36px 4px,\\n    48px 4px\\n  );\\n  --body-inner: polygon(\\n    48px 0,\\n    calc(100% - 48px) 0,\\n    calc(100% - 48px) 4px,\\n    calc(100% - 36px) 4px,\\n    calc(100% - 36px) 8px,\\n    calc(100% - 28px) 8px,\\n    calc(100% - 28px) 12px,\\n    calc(100% - 20px) 12px,\\n    calc(100% - 20px) 16px,\\n    calc(100% - 16px) 16px,\\n    calc(100% - 16px) 20px,\\n    calc(100% - 12px) 20px,\\n    calc(100% - 12px) 24px,\\n    calc(100% - 8px) 24px,\\n    calc(100% - 8px) 32px,\\n    calc(100% - 4px) 32px,\\n    calc(100% - 4px) 40px,\\n    100% 40px,\\n    100% calc(100% - 40px),\\n    calc(100% - 4px) calc(100% - 40px),\\n    calc(100% - 4px) calc(100% - 32px),\\n    calc(100% - 8px) calc(100% - 32px),\\n    calc(100% - 8px) calc(100% - 24px),\\n    calc(100% - 12px) calc(100% - 24px),\\n    calc(100% - 12px) calc(100% - 20px),\\n    calc(100% - 16px) calc(100% - 20px),\\n    calc(100% - 16px) calc(100% - 16px),\\n    calc(100% - 20px) calc(100% - 16px),\\n    calc(100% - 20px) calc(100% - 12px),\\n    calc(100% - 28px) calc(100% - 12px),\\n    calc(100% - 28px) calc(100% - 8px),\\n    calc(100% - 36px) calc(100% - 8px),\\n    calc(100% - 36px) calc(100% - 4px),\\n    calc(100% - 48px) calc(100% - 4px),\\n    calc(100% - 48px) 100%,\\n    48px 100%,\\n    48px calc(100% - 4px),\\n    36px calc(100% - 4px),\\n    36px calc(100% - 8px),\\n    28px calc(100% - 8px),\\n    28px calc(100% - 12px),\\n    20px calc(100% - 12px),\\n    20px calc(100% - 16px),\\n    16px calc(100% - 16px),\\n    16px calc(100% - 20px),\\n    12px calc(100% - 20px),\\n    12px calc(100% - 24px),\\n    8px calc(100% - 24px),\\n    8px calc(100% - 32px),\\n    4px calc(100% - 32px),\\n    4px calc(100% - 40px),\\n    0 calc(100% - 40px),\\n    0 40px,\\n    4px 40px,\\n    4px 32px,\\n    8px 32px,\\n    8px 24px,\\n    12px 24px,\\n    12px 20px,\\n    16px 20px,\\n    16px 16px,\\n    20px 16px,\\n    20px 12px,\\n    28px 12px,\\n    28px 8px,\\n    36px 8px,\\n    36px 4px,\\n    48px 4px\\n  );\\n}\\n\\n/* 外框層：深棕色，剪成外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -4px;\\n  z-index: -1;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--body-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  z-index: -1;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 4px 4px 0 rgb(251 248 241 / 45%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--body-inner);\\n  pointer-events: none;\\n}", "js": ""}' WHERE name = '圓滾滾';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
