px),\\n    20px calc(100% - 12px),\\n    20px calc(100% - 16px),\\n    16px calc(100% - 16px),\\n    16px calc(100% - 20px),\\n    12px calc(100% - 20px),\\n    12px calc(100% - 24px),\\n    8px calc(100% - 24px),\\n    8px calc(100% - 32px),\\n    4px calc(100% - 32px),\\n    4px calc(100% - 40px),\\n    0 calc(100% - 40px),\\n    0 40px,\\n    4px 40px,\\n    4px 32px,\\n    8px 32px,\\n    8px 24px,\\n    12px 24px,\\n    12px 20px,\\n    16px 20px,\\n    16px 16px,\\n    20px 16px,\\n    20px 12px,\\n    28px 12px,\\n    28px 8px,\\n    36px 8px,\\n    36px 4px,\\n    48px 4px\\n  );\\n}\\n\\n/* 外框層：深棕色，剪成外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -4px;\\n  z-index: -1;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--body-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  z-index: -1;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 4px 4px 0 rgb(251 248 241 / 45%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--body-inner);\\n  pointer-events: none;\\n}", "js": ""}'
