UPDATE parts SET category = 'css', slot = 'body', price = 30, starter_code = '{"html": "", "css": "/* 想換顏色、移位置，改這裡就好 */\\n/* --caramel-color 是焦糖的顏色，--caramel-height 是焦糖的厚度 */\\n/* 眼睛往下一點，才不會壓到焦糖 */\\n.body {\\n  --caramel-color: #8a4f1d;\\n  --caramel-height: 24px;\\n  --eye-y: 34%;\\n  /* 圓角看不到，但點身體的範圍會跟著變圓 */\\n  border-radius: 30px 30px 10px 10px;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* .body 只當透明的容器，看得到的身體畫在後面兩層，零件就不會被剪掉 */\\n/* background-clip: text 讓 .body 的底色只畫在文字裡，.body 沒有文字就看不到；::after 用 background: inherit 拿到同一個底色 */\\n/* 左邊、上面的點從左上角量；右邊、下面的點用 calc(100% - ...) 從右下角量，身體變寬變高時形狀跟著撐開 */\\n.body {\\n  border-color: transparent;\\n  -webkit-background-clip: text;\\n  background-clip: text;\\n  --body-outer: polygon(\\n    20px 0,\\n    calc(100% - 20px) 0,\\n    calc(100% - 20px) 4px,\\n    calc(100% - 12px) 4px,\\n    calc(100% - 12px) 8px,\\n    calc(100% - 8px) 8px,\\n    calc(100% - 8px) 12px,\\n    calc(100% - 4px) 12px,\\n    calc(100% - 4px) 20px,\\n    100% 20px,\\n    100% calc(100% - 4px),\\n    calc(100% - 4px) calc(100% - 4px),\\n    calc(100% - 4px) 100%,\\n    4px 100%,\\n    4px calc(100% - 4px),\\n    0 calc(100% - 4px),\\n    0 20px,\\n    4px 20px,\\n    4px 12px,\\n    8px 12px,\\n    8px 8px,\\n    12px 8px,\\n    12px 4px,\\n    20px 4px\\n  );\\n  --body-inner: polygon(\\n    20px 0,\\n    calc(100% - 20px) 0,\\n    calc(100% - 20px) 4px,\\n    calc(100% - 12px) 4px,\\n    calc(100% - 12px) 8px,\\n    calc(100% - 8px) 8px,\\n    calc(100% - 8px) 12px,\\n    calc(100% - 4px) 12px,\\n    calc(100% - 4px) 20px,\\n    100% 20px,\\n    100% calc(100% - 4px),\\n    calc(100% - 4px) calc(100% - 4px),\\n    calc(100% - 4px) 100%,\\n    4px 100%,\\n    4px calc(100% - 4px),\\n    0 calc(100% - 4px),\\n    0 20px,\\n    4px 20px,\\n    4px 12px,\\n    8px 12px,\\n    8px 8px,\\n    12px 8px,\\n    12px 4px,\\n    20px 4px\\n  );\\n}\\n\\n/* 外框層：深棕色，剪成外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -4px;\\n  z-index: -1;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--body-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格；焦糖用 inset 陰影畫在這一層上面 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  z-index: -1;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 0 var(--caramel-height) 0 var(--caramel-color),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--body-inner);\\n  pointer-events: none;\\n}", "js": ""}' WHERE name = '布丁';
