SELECT '布丁', 'css', 'body', 30, 'body.svg', '{"html": "", "css": "/* 想換顏色、移位置，改這裡就好 */\\n/* --caramel-color 是焦糖的顏色，--caramel-height 是焦糖的厚度 */\\n/* 眼睛往下一點，才不會壓到焦糖 */\\n.body {\\n  --caramel-color: #8a4f1d;\\n  --caramel-height: 24px;\\n  --eye-y: 34%;\\n  /* 圓角看不到，但點身體的範圍會跟著變圓 */\\n  border-radius: 30px 30px 10px 10px;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* .body 只當透明的容器，看得到的身體畫在後面兩層，零件就不會被剪掉 */\\n/* background-clip: text 讓 .body 的底色只畫在文字裡，.body 沒有文字就看不到；::after 用 background: inherit 拿到同一個底色 */\\n/* 左邊、上面的點從左上角量；右邊、下面的點用 calc(100% - ...) 從右下角量，身體變寬變高時形狀跟著撐開 */\\n.body {\\n  border-color: transparent;\\n  -webkit-background-clip: text;\\n  background-clip: text;\\n  --body-outer: polygon(\\n    20px 0,\\n    calc(100% - 20px) 0,\\n    calc(100% - 20px) 4px,\\n    calc(100% - 12px) 4px,\\n    calc(100% - 12px) 8px,\\n    calc(100% - 8px) 8px,\\n    calc(100% - 8px) 12px,\\n    calc(100% - 4px) 12px,\\n    calc(100% - 4px) 20px,\\n    100% 20px,\\n    100% calc(100% - 4px),\\n    calc(100% - 4px) calc(100% - 4px),\\n    calc(100% - 4px) 100%,\\n    4px 100%,\\n    4px calc(100% - 4px),\\n    0 calc(100% - 4px),\\n    0 20px,\\n    4px 20px,\\n    4px 12px,\\n    8px 12px,\\n    8px 8px,\\n    12px 8px,\\n    12px 4px,\\n    20px 4px\\n  );\\n  --body-inner: polygon(\\n    20px 0,\\n    calc(100% - 20px) 0,\\n    calc(100% - 20px) 4px,\\n    calc(100% - 12px) 4px,\\n    calc(100% - 12px) 8px,\\n    calc(100% - 8px) 8px,\\n    calc(100% - 8px) 12px,\\n    calc(100% - 4px) 12px,\\n    calc(100% - 4px) 20px,\\n    100% 20px,\\n    100% calc(100% - 4px),\\n    calc(100% - 4px) calc(100% - 4px),\\n    calc(100% - 4px) 100%,\\n    4px 100%,\\n    4px calc(100% - 4px),\\n    0 calc(100% - 4px),\\n    0 20px,\\n    4px 20px,\\n    4px 12px,\\n    8px 12px,\\n    8px 8px,\\n    12px 8px,\\n    12px 4px,\\n    20px 4px\\n  );\\n}\\n\\n/* 外框層：深棕色，剪成外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -4px;\\n  z-index: -1;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--body-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格；焦糖用 inset 陰影畫在這一層上面 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  z-index: -1;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 0 var(--caramel-height) 0 var(--caramel-color),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--body-inner);\\n  pointer-events: none;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '布丁');

-- body：雲朵
UPDATE parts SET category = 'css', slot = 'body', price = 40, starter_code = '{"html": "", "css": "/* 想換顏色、移位置，改這裡就好 */\\n/* 頭上兩顆圓凸起和身體畫成同一個形狀；角往上移到凸起上面，對話框也抬高到凸起上面 */\\n.body {\\n  --horn-y: -56%;\\n  --wing-x: 4px;\\n}\\n\\n.chimera {\\n  --speech-y: 122px;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* .body 只當透明的容器，看得到的雲朵畫在後面兩層，零件就不會被剪掉 */\\n/* background-clip: text 讓 .body 的底色只畫在文字裡，.body 沒有文字就看不到；::after 用 background: inherit 拿到同一個底色 */\\n.body {\\n  border-color: transparent;\\n  -webkit-background-clip: text;\\n  background-clip: text;\\n}\\n\\n/* 外框層：深棕色，剪成雲朵外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -68px auto auto -4px;\\n  z-index: -1;\\n  width: 128px;\\n  height: 172px;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--cloud-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: -64px auto auto 0;\\n  z-index: -1;\\n  width: 120px;\\n  height: 164px;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 4px 4px 0 rgb(251 248 241 / 45%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--cloud-inner);\\n  pointer-events: none;\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角 */\\n.body {\\n  --cloud-outer: polygon(\\n    72px 4px,\\n    96px 4px,\\n    96px 8px,\\n    104px 8px,\\n    104px 12px,\\n    108px 12px,\\n    108px 16px,\\n    112px 16px,\\n    112px 20px,\\n    116px 20px,\\n    116px 36px,\\n    120px 36px,\\n    120px 40px,\\n    116px 40px,\\n    116px 56px,\\n    112px 56px,\\n    112px 60px,\\n    108px 60px,\\n    108px 64px,\\n    104px 64px,\\n    104px 72px,\\n    108px 72px,\\n    108px 76px,\\n    112px 76px,\\n    112px 80px,\\n    116px 80px,\\n    116px 84px,\\n    120px 84px,\\n    120px 88px,\\n    124px 88px,\\n    124px 100px,\\n    128px 100px,\\n    128px 136px,\\n    124px 136px,\\n    124px 148px,\\n    120px 148px,\\n    120px 152px,\\n    116px 152px,\\n    116px 156px,\\n    112px 156px,\\n    112px 160px,\\n    108px 160px,\\n    108px 164px,\\n    104px 164px,\\n    104px 168px,\\n    92px 168px,\\n    92px 172px,\\n    36px 172px,\\n    36px 168px,\\n    24px 168px,\\n    24px 164px,\\n    20px 164px,\\n    20px 160px,\\n    16px 160px,\\n    16px 156px,\\n    12px 156px,\\n    12px 152px,\\n    8px 152px,\\n    8px 148px,\\n    4px 148px,\\n    4px 136px,\\n    0 136px,\\n    0 100px,\\n    4px 100px,\\n    4px 88px,\\n    8px 88px,\\n    8px 84px,\\n    12px 84px,\\n    12px 80px,\\n    16px 80px,\\n    16px 76px,\\n    20px 76px,\\n    20px 72px,\\n    24px 72px,\\n    24px 68px,\\n    32px 68px,\\n    32px 64px,\\n    28px 64px,\\n    28px 60px,\\n    24px 60px,\\n    24px 52px,\\n    20px 52px,\\n    20px 32px,\\n    24px 32px,\\n    24px 24px,\\n    28px 24px,\\n    28px 20px,\\n    36px 20px,\\n    36px 16px,\\n    60px 16px,\\n    60px 12px,\\n    64px 12px,\\n    64px 8px,\\n    72px 8px\\n  );\\n  --cloud-inner: polygon(\\n    72px 4px,\\n    88px 4px,\\n    88px 8px,\\n    96px 8px,\\n    96px 12px,\\n    100px 12px,\\n    100px 16px,\\n    104px 16px,\\n    104px 20px,\\n    108px 20px,\\n    108px 48px,\\n    104px 48px,\\n    104px 52px,\\n    100px 52px,\\n    100px 56px,\\n    96px 56px,\\n    96px 72px,\\n    100px 72px,\\n    100px 76px,\\n    104px 76px,\\n    104px 80px,\\n    108px 80px,\\n    108px 84px,\\n    112px 84px,\\n    112px 88px,\\n    116px 88px,\\n    116px 100px,\\n    120px 100px,\\n    120px 128px,\\n    116px 128px,\\n    116px 140px,\\n    112px 140px,\\n    112px 144px,\\n    108px 144px,\\n    108px 148px,\\n    104px 148px,\\n    104px 152px,\\n    100px 152px,\\n    100px 156px,\\n    96px 156px,\\n    96px 160px,\\n    84px 160px,\\n    84px 164px,\\n    36px 164px,\\n    36px 160px,\\n    24px 160px,\\n    24px 156px,\\n    20px 156px,\\n    20px 152px,\\n    16px 152px,\\n    16px 148px,\\n    12px 148px,\\n    12px 144px,\\n    8px 144px,\\n    8px 140px,\\n    4px 140px,\\n    4px 128px,\\n    0 128px,\\n    0 100px,\\n    4px 100px,\\n    4px 88px,\\n    8px 88px,\\n    8px 84px,\\n    12px 84px,\\n    12px 80px,\\n    16px 80px,\\n    16px 76px,\\n    20px 76px,\\n    20px 72px,\\n    24px 72px,\\n    24px 68px,\\n    32px 68px,\\n    32px 56px,\\n    28px 56px,\\n    28px 52px,\\n    24px 52px,\\n    24px 44px,\\n    20px 44px,\\n    20px 32px,\\n    24px 32px,\\n    24px 24px,\\n    28px 24px,\\n    28px 20px,\\n    36px 20px,\\n    36px 16px,\\n    60px 16px,\\n    60px 12px,\\n    64px 12px,\\n    64px 8px,\\n    72px 8px\\n  );\\n}", "js": ""}' WHERE name = '雲朵';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '雲朵', 'css', 'body', 40, 'body.svg', '{"html": "", "css": "/* 想換顏色、移位置，改這裡就好 */\\n/* 頭上兩顆圓凸起和身體畫成同一個形狀；角往上移到凸起上面，對話框也抬高到凸起上面 */\\n.body {\\n  --horn-y: -56%;\\n  --wing-x: 4px;\\n}\\n\\n.chimera {\\n  --speech-y: 122px;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* .body 只當透明的容器，看得到的雲朵畫在後面兩層，零件就不會被剪掉 */\\n/* background-clip: text 讓 .body 的底色只畫在文字裡，.body 沒有文字就看不到；::after 用 background: inherit 拿到同一個底色 */\\n.body {\\n  border-color: transparent;\\n  -webkit-background-clip: text;\\n  background-clip: text;\\n}\\n\\n/* 外框層：深棕色，剪成雲朵外面那一圈 */\\n.body::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: -68px auto auto -4px;\\n  z-index: -1;\\n  width: 128px;\\n  height: 172px;\\n  background: #4a3426;\\n  border: 0;\\n  border-radius: 0;\\n  clip-path: var(--cloud-outer);\\n  pointer-events: none;\\n}\\n\\n/* 底色層：繼承 .body 的毛色和花紋，比外框層往內縮一格 */\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  inset: -64px auto auto 0;\\n  z-index: -1;\\n  width: 120px;\\n  height: 164px;\\n  background: inherit;\\n  -webkit-background-clip: border-box;\\n  background-clip: border-box;\\n  border-radius: 0;\\n  box-shadow:\\n    inset 4px 4px 0 rgb(251 248 241 / 45%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--cloud-inner);\\n  pointer-events: none;\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角 */\\n.body {\\n  --cloud-outer: polygon(\\n    72px 4px,\\n    96px 4px,\\n    96px 8px,\\n    104px 8px,\\n    104px 12px,\\n    108px 12px,\\n    108px 16px,\\n    112px 16px,\\n    112px 20px,\\n    116px 20px,\\n    116px 36px,\\n    120px 36px,\\n    120px 40px,\\n    116px 40px,\\n    116px 56px,\\n    112px 56px,\\n    112px 60px,\\n    108px 60px,\\n    108px 64px,\\n    104px 64px,\\n    104px 72px,\\n    108px 72px,\\n    108px 76px,\\n    112px 76px,\\n    112px 80px,\\n    116px 80px,\\n    116px 84px,\\n    120px 84px,\\n    120px 88px,\\n    124px 88px,\\n    124px 100px,\\n    128px 100px,\\n    128px 136px,\\n    124px 136px,\\n    124px 148px,\\n    120px 148px,\\n    120px 152px,\\n    116px 152px,\\n    116px 156px,\\n    112px 156px,\\n    112px 160px,\\n    108px 160px,\\n    108px 164px,\\n    104px 164px,\\n    104px 168px,\\n    92px 168px,\\n    92px 172px,\\n    36px 172px,\\n    36px 168px,\\n    24px 168px,\\n    24px 164px,\\n    20px 164px,\\n    20px 160px,\\n    16px 160px,\\n    16px 156px,\\n    12px 156px,\\n    12px 152px,\\n    8px 152px,\\n    8px 148px,\\n    4px 148px,\\n    4px 136px,\\n    0 136px,\\n    0 100px,\\n    4px 100px,\\n    4px 88px,\\n    8px 88px,\\n    8px 84px,\\n    12px 84px,\\n    12px 80px,\\n    16px 80px,\\n    16px 76px,\\n    20px 76px,\\n    20px 72px,\\n    24px 72px,\\n    24px 68px,\\n    32px 68px,\\n    32px 64px,\\n    28px 64px,\\n    28px 60px,\\n    24px 60px,\\n    24px 52px,\\n    20px 52px,\\n    20px 32px,\\n    24px 32px,\\n    24px 24px,\\n    28px 24px,\\n    28px 20px,\\n    36px 20px,\\n    36px 16px,\\n    60px 16px,\\n    60px 12px,\\n    64px 12px,\\n    64px 8px,\\n    72px 8px\\n  );\\n  --cloud-inner: polygon(\\n    72px 4px,\\n    88px 4px,\\n    88px 8px,\\n    96px 8px,\\n    96px 12px,\\n    100px 12px,\\n    100px 16px,\\n    104px 16px,\\n    104px 20px,\\n    108px 20px,\\n    108px 48px,\\n    104px 48px,\\n    104px 52px,\\n    100px 52px,\\n    100px 56px,\\n    96px 56px,\\n    96px 72px,\\n    100px 72px,\\n    100px 76px,\\n    104px 76px,\\n    104px 80px,\\n    108px 80px,\\n    108px 84px,\\n    112px 84px,\\n    112px 88px,\\n    116px 88px,\\n    116px 100px,\\n    120px 100px,\\n    120px 128px,\\n    116px 128px,\\n    116px 140px,\\n    112px 140px,\\n    112px 144px,\\n    108px 144px,\\n    108px 148px,\\n    104px 148px,\\n    104px 152px,\\n    100px 152px,\\n    100px 156px,\\n    96px 156px,\\n    96px 160px,\\n    84px 160px,\\n    84px 164px,\\n    36px 164px,\\n    36px 160px,\\n    24px 160px,\\n    24px 156px,\\n    20px 156px,\\n    20px 152px,\\n    16px 152px,\\n    16px 148px,\\n    12px 148px,\\n    12px 144px,\\n    8px 144px,\\n    8px 140px,\\n    4px 140px,\\n    4px 128px,\\n    0 128px,\\n    0 100px,\\n    4px 100px,\\n    4px 88px,\\n    8px 88px,\\n    8px 84px,\\n    12px 84px,\\n    12px 80px,\\n    16px 80px,\\n    16px 76px,\\n    20px 76px,\\n    20px 72px,\\n    24px 72px,\\n    24px 68px,\\n    32px 68px,\\n    32px 56px,\\n    28px 56px,\\n    28px 52px,\\n    24px 52px,\\n    24px 44px,\\n    20px 44px,\\n    20px 32px,\\n    24px 32px,\\n    24px 24px,\\n    28px 24px,\\n    28px 20px,\\n    36px 20px,\\n    36px 16px,\\n    60px 16px,\\n    60px 12px,\\n    64px 12px,\\n    64px 8px,\\n    72px 8px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '雲朵');

-- body：會呼吸的身體
UPDATE parts SET category = 'css', slot = 'body', price = 40, starter_code = '{"html": "", "css": "/* 待機的時候一直慢慢呼吸，不用 JS 觸發 */\\n/* 放在外層的 .chimera：點一下跳是放在 .body，兩個動畫在不同元素上，不會互相蓋掉 */\\n/* 用 scale 不用 transform，商店小預覽縮小 .chimera 用的是 transform，兩個會疊在一起 */\\n/* 改 2.4s 調呼吸快慢，改 1.06 調放大多少 */\\n.chimera {\\n  animation: body-breathe 2.4s ease-in-out infinite;\\n}\\n\\n@keyframes body-breathe {\\n  50% {\\n    scale: 1.06;\\n  }\\n}", "js": ""}' WHERE name = '會呼吸的身體';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會呼吸的身體', 'css', 'body', 40, 'body.svg', '{"html": "", "css": "/* 待機的時候一直慢慢呼吸，不用 JS 觸發 */\\n/* 放在外層的 .chimera：點一下跳是放在 .body，兩個動畫在不同元素上，不會互相蓋掉 */\\n/* 用 scale 不用 transform，商店小預覽縮小 .chimera 用的是 transform，兩個會疊在一起 */\\n/* 改 2.4s 調呼吸快慢，改 1.06 調放大多少 */\\n.chimera {\\n  animation: body-breathe 2.4s ease-in-out infinite;\\n}\\n\\n@keyframes body-breathe {\\n  50% {\\n    scale: 1.06;\\n  }\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會呼吸的身體');

-- body：會變形的身體
UPDATE parts SET category = 'js', slot = 'body', price = 60, starter_code = '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: border-radius 0.3s;\\n}\\n\\n/* 每個形狀一個 class，想加形狀就多寫一個 .shape-4，JS 那邊的 4 也要改成 5 */\\n/* 每個形狀也調整角、腳、翅膀的位置，零件才會貼著身體 */\\n.body.shape-1 {\\n  --horn-y: 7%;\\n  --leg-y: 93%;\\n  --wing-x: 5px;\\n  border-radius: 50%;\\n}\\n\\n.body.shape-2 {\\n  --horn-y: 8%;\\n  --wing-x: 8px;\\n  border-radius: 60px 60px 8px 8px;\\n}\\n\\n.body.shape-3 {\\n  --horn-y: 8%;\\n  --leg-y: 94%;\\n  --wing-x: 8px;\\n  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;\\n}", "js": "// 點身體輪流換形狀：形狀寫在 CSS 的 .shape-1 ~ .shape-3，JS 只負責換 class\\nconst morphBody = document.querySelector(\'.body\')\\nlet morphIndex = 0\\nmorphBody.addEventListener(\'click\', () => {\\n  morphBody.classList.remove(`shape-${morphIndex}`)\\n  morphIndex = (morphIndex + 1) % 4\\n  if (morphIndex) morphBody.classList.add(`shape-${morphIndex}`)\\n})"}' WHERE name = '會變形的身體';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會變形的身體', 'js', 'body', 60, 'body.svg', '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: border-radius 0.3s;\\n}\\n\\n/* 每個形狀一個 class，想加形狀就多寫一個 .shape-4，JS 那邊的 4 也要改成 5 */\\n/* 每個形狀也調整角、腳、翅膀的位置，零件才會貼著身體 */\\n.body.shape-1 {\\n  --horn-y: 7%;\\n  --leg-y: 93%;\\n  --wing-x: 5px;\\n  border-radius: 50%;\\n}\\n\\n.body.shape-2 {\\n  --horn-y: 8%;\\n  --wing-x: 8px;\\n  border-radius: 60px 60px 8px 8px;\\n}\\n\\n.body.shape-3 {\\n  --horn-y: 8%;\\n  --leg-y: 94%;\\n  --wing-x: 8px;\\n  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;\\n}", "js": "// 點身體輪流換形狀：形狀寫在 CSS 的 .shape-1 ~ .shape-3，JS 只負責換 class\\nconst morphBody = document.querySelector(\'.body\')\\nlet morphIndex = 0\\nmorphBody.addEventListener(\'click\', () => {\\n  morphBody.classList.remove(`shape-${morphIndex}`)\\n  morphIndex = (morphIndex + 1) % 4\\n  if (morphIndex) morphBody.classList.add(`shape-${morphIndex}`)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會變形的身體');

-- horn：小角
UPDATE parts SET category = 'html', slot = 'horn', price = 10, starter_code = '{"html": "<div class=\\"horn\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n  left: calc(50% - 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 角分三層，由下往上寬 5 格、3 格、1 格，疊起來就是一階一階的尖角 */\\n/* 一格是 4px，外框也是一格；上面兩層沒有下框，往下蓋住下一層的上框，三層才會連在一起 */\\n.horn {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 中間那層 */\\n.horn::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 最上面的尖端 */\\n.horn::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 4px;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}", "js": ""}' WHERE name = '小角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '小角', 'html', 'horn', 10, 'horn.svg', '{"html": "<div class=\\"horn\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n  left: calc(50% - 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 角分三層，由下往上寬 5 格、3 格、1 格，疊起來就是一階一階的尖角 */\\n/* 一格是 4px，外框也是一格；上面兩層沒有下框，往下蓋住下一層的上框，三層才會連在一起 */\\n.horn {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 中間那層 */\\n.horn::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 最上面的尖端 */\\n.horn::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 4px;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '小角');

-- horn：雙角
UPDATE parts SET category = 'html', slot = 'horn', price = 15, starter_code = '{"html": "<div class=\\"horn-twin left\\"></div>\\n<div class=\\"horn-twin right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-twin {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n}\\n\\n.horn-twin.left {\\n  left: calc(50% - 40px);\\n}\\n\\n.horn-twin.right {\\n  left: calc(50% + 20px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每支角兩層：下層 3 × 2 格，上層 1 格寬的尖端 */\\n.horn-twin {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 尖端：沒有下框，往下蓋住下層的上框，兩層才會連在一起 */\\n.horn-twin::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}", "js": ""}' WHERE name = '雙角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '雙角', 'html', 'horn', 15, 'horn.svg', '{"html": "<div class=\\"horn-twin left\\"></div>\\n<div class=\\"horn-twin right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-twin {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n}\\n\\n.horn-twin.left {\\n  left: calc(50% - 40px);\\n}\\n\\n.horn-twin.right {\\n  left: calc(50% + 20px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每支角兩層：下層 3 × 2 格，上層 1 格寬的尖端 */\\n.horn-twin {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 尖端：沒有下框，往下蓋住下層的上框，兩層才會連在一起 */\\n.horn-twin::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '雙角');

-- horn：獨角獸角
UPDATE parts SET category = 'css', slot = 'horn', price = 20, starter_code = '{"html": "<div class=\\"horn-unicorn\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-unicorn {\\n  --horn-color: #fbf8f1;\\n  --stripe-color: #e8a0a0;\\n  top: calc(var(--horn-y, 0%) - 20px);\\n  left: calc(50% - 10px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下層 3 × 3 格，上面接一根 1 格寬、4 格高的尖端 */\\n/* 條紋是一格白、一格粉紅一直重複，邊緣是直的，跟像素圖一樣 */\\n.horn-unicorn,\\n.horn-unicorn::before {\\n  background: repeating-linear-gradient(\\n    var(--horn-color) 0 4px,\\n    var(--stripe-color) 4px 8px\\n  );\\n  border: 4px solid #4a3426;\\n}\\n\\n.horn-unicorn {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 12px;\\n}\\n\\n/* 尖端：沒有下框，往下蓋住下層的上框 */\\n.horn-unicorn::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 0;\\n  width: 4px;\\n  height: 16px;\\n  border-bottom: 0;\\n}", "js": ""}' WHERE name = '獨角獸角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '獨角獸角', 'css', 'horn', 20, 'horn.svg', '{"html": "<div class=\\"horn-unicorn\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-unicorn {\\n  --horn-color: #fbf8f1;\\n  --stripe-color: #e8a0a0;\\n  top: calc(var(--horn-y, 0%) - 20px);\\n  left: calc(50% - 10px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下層 3 × 3 格，上面接一根 1 格寬、4 格高的尖端 */\\n/* 條紋是一格白、一格粉紅一直重複，邊緣是直的，跟像素圖一樣 */\\n.horn-unicorn,\\n.horn-unicorn::before {\\n  background: repeating-linear-gradient(\\n    var(--horn-color) 0 4px,\\n    var(--stripe-color) 4px 8px\\n  );\\n  border: 4px solid #4a3426;\\n}\\n\\n.horn-unicorn {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 12px;\\n}\\n\\n/* 尖端：沒有下框，往下蓋住下層的上框 */\\n.horn-unicorn::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 0;\\n  width: 4px;\\n  height: 16px;\\n  border-bottom: 0;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '獨角獸角');

-- horn：鹿角
UPDATE parts SET category = 'html', slot = 'horn', price = 25, starter_code = '{"html": "<div class=\\"horn-deer left\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>\\n<div class=\\"horn-deer right\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-deer {\\n  --antler-color: #9a6440;\\n  top: calc(var(--horn-y, 0%) - 36px);\\n}\\n\\n.horn-deer.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.horn-deer.right {\\n  left: calc(50% + 24px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一根 2 格寬的主幹，旁邊伸出一根分岔，分岔尾端再往上長一段，全部都是方塊 */\\n/* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著整支鹿角的形狀走 */\\n.horn-deer {\\n  position: absolute;\\n  z-index: 1;\\n  width: 8px;\\n  height: 36px;\\n  background: var(--antler-color);\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.horn-deer-branch {\\n  position: absolute;\\n  top: 12px;\\n  width: 12px;\\n  height: 8px;\\n  background: var(--antler-color);\\n}\\n\\n/* 分岔往外長：左邊的往左、右邊的往右 */\\n.horn-deer.left .horn-deer-branch {\\n  left: -12px;\\n}\\n\\n.horn-deer.right .horn-deer-branch {\\n  left: 8px;\\n}\\n\\n.horn-deer-branch::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  width: 8px;\\n  height: 12px;\\n  background: var(--antler-color);\\n}\\n\\n.horn-deer.left .horn-deer-branch::after {\\n  left: 0;\\n}\\n\\n.horn-deer.right .horn-deer-branch::after {\\n  right: 0;\\n}", "js": ""}' WHERE name = '鹿角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '鹿角', 'html', 'horn', 25, 'horn.svg', '{"html": "<div class=\\"horn-deer left\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>\\n<div class=\\"horn-deer right\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-deer {\\n  --antler-color: #9a6440;\\n  top: calc(var(--horn-y, 0%) - 36px);\\n}\\n\\n.horn-deer.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.horn-deer.right {\\n  left: calc(50% + 24px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一根 2 格寬的主幹，旁邊伸出一根分岔，分岔尾端再往上長一段，全部都是方塊 */\\n/* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著整支鹿角的形狀走 */\\n.horn-deer {\\n  position: absolute;\\n  z-index: 1;\\n  width: 8px;\\n  height: 36px;\\n  background: var(--antler-color);\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.horn-deer-branch {\\n  position: absolute;\\n  top: 12px;\\n  width: 12px;\\n  height: 8px;\\n  background: var(--antler-color);\\n}\\n\\n/* 分岔往外長：左邊的往左、右邊的往右 */\\n.horn-deer.left .horn-deer-branch {\\n  left: -12px;\\n}\\n\\n.horn-deer.right .horn-deer-branch {\\n  left: 8px;\\n}\\n\\n.horn-deer-branch::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  width: 8px;\\n  height: 12px;\\n  background: var(--antler-color);\\n}\\n\\n.horn-deer.left .horn-deer-branch::after {\\n  left: 0;\\n}\\n\\n.horn-deer.right .horn-deer-branch::after {\\n  right: 0;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '鹿角');

-- horn：牛角
UPDATE parts SET category = 'css', slot = 'horn', price = 20, starter_code = '{"html": "<div class=\\"horn-ox left\\"></div>\\n<div class=\\"horn-ox right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-ox {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n}\\n\\n.horn-ox.left {\\n  left: calc(50% - 72px);\\n}\\n\\n.horn-ox.right {\\n  left: calc(50% + 40px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一條往外長的橫條，末端往上翹兩格，看起來就是彎彎的牛角 */\\n.horn-ox {\\n  position: absolute;\\n  z-index: 1;\\n  width: 24px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 往上翹的那段：沒有下框，往下蓋住橫條的上框，兩塊才會連在一起 */\\n.horn-ox::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -16px;\\n  width: 8px;\\n  height: 12px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}\\n\\n.horn-ox.left::before {\\n  left: -4px;\\n}\\n\\n.horn-ox.right::before {\\n  right: -4px;\\n}", "js": ""}' WHERE name = '牛角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '牛角', 'css', 'horn', 20, 'horn.svg', '{"html": "<div class=\\"horn-ox left\\"></div>\\n<div class=\\"horn-ox right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-ox {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n}\\n\\n.horn-ox.left {\\n  left: calc(50% - 72px);\\n}\\n\\n.horn-ox.right {\\n  left: calc(50% + 40px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一條往外長的橫條，末端往上翹兩格，看起來就是彎彎的牛角 */\\n.horn-ox {\\n  position: absolute;\\n  z-index: 1;\\n  width: 24px;\\n  height: 8px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 往上翹的那段：沒有下框，往下蓋住橫條的上框，兩塊才會連在一起 */\\n.horn-ox::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -16px;\\n  width: 8px;\\n  height: 12px;\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}\\n\\n.horn-ox.left::before {\\n  left: -4px;\\n}\\n\\n.horn-ox.right::before {\\n  right: -4px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '牛角');

