UPDATE parts SET category = 'html', slot = 'horn', price = 20, starter_code = '{"html": "<div class=\\"horn-cat left\\"></div>\\n<div class=\\"horn-cat right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-cat {\\n  --ear-color: #9a6440;\\n  --ear-inner: #e8a0a0;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n}\\n\\n.horn-cat.left {\\n  left: calc(50% - 50px);\\n}\\n\\n.horn-cat.right {\\n  left: calc(50% + 22px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 耳朵三層，由下往上寬 5 格、3 格、1 格；中間那層是粉紅色的耳朵內側 */\\n.horn-cat {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 8px;\\n  background: var(--ear-color);\\n  border: 4px solid #4a3426;\\n}\\n\\n/* 上面兩層沒有下框，往下蓋住下一層的上框，三層才會連在一起 */\\n.horn-cat::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--ear-inner);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}\\n\\n.horn-cat::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 4px;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--ear-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}", "js": ""}' WHERE name = '貓耳';
