-- horn：兔耳
UPDATE parts SET category = 'html', slot = 'horn', price = 20, starter_code = '{"html": "<div class=\\"horn-bunny left\\"></div>\\n<div class=\\"horn-bunny right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.horn-bunny {\\n  --ear-color: #fbf8f1;\\n  --ear-inner: #e8a0a0;\\n  top: calc(var(--horn-y, 0%) - 48px);\\n}\\n\\n.horn-bunny.left {\\n  left: calc(50% - 34px);\\n}\\n\\n.horn-bunny.right {\\n  left: calc(50% + 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻耳朵 3 格寬、10 格高，頂端多一格收尖 */\\n.horn-bunny {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 40px;\\n  background: var(--ear-color);\\n  border: 4px solid #4a3426;\\n}\\n\\n/* 頂端：沒有下框，往下蓋住耳朵的上框 */\\n.horn-bunny::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--ear-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}\\n\\n/* 中間一條粉紅色的耳朵內側，1 格寬 */\\n.horn-bunny::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 32px;\\n  background: var(--ear-inner);\\n}", "js": ""}' WHERE name = '兔耳';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
