FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '兔耳');

-- horn：會變色的角
UPDATE parts SET category = 'js', slot = 'horn', price = 50, starter_code = '{"html": "<div class=\\"horn-color\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好；點角的時候 JS 會改 --horn-color */\\n.horn-color {\\n  --horn-color: #fbf8f1;\\n  top: calc(var(--horn-y, 0%) - 16px);\\n  left: calc(50% - 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 角分三層，由下往上寬 5 格、3 格、1 格；三層都用 --horn-color，換色時一起變 */\\n.horn-color,\\n.horn-color::before,\\n.horn-color::after {\\n  background: var(--horn-color);\\n  border: 4px solid #4a3426;\\n  transition: background-color 0.3s;\\n}\\n\\n.horn-color {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 8px;\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n  cursor: pointer;\\n}\\n\\n/* 上面兩層沒有下框，往下蓋住下一層的上框，三層才會連在一起 */\\n.horn-color::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  left: 0;\\n  width: 12px;\\n  height: 12px;\\n  border-bottom: 0;\\n}\\n\\n.horn-color::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -20px;\\n  left: 4px;\\n  width: 4px;\\n  height: 8px;\\n  border-bottom: 0;\\n}", "js": "// 點角換一個隨機顏色\\nconst colorHorn = document.querySelector(\'.horn-color\')\\ncolorHorn.addEventListener(\'click\', (event) => {\\n  // 角長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  const hue = Math.floor(Math.random() * 360)\\n  colorHorn.style.setProperty(\'--horn-color\', `hsl(${hue}, 70%, 65%)`)\\n})"}' WHERE name = '會變色的角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
