FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會變色的角');

-- eyes：眼睛
UPDATE parts SET category = 'html', slot = 'eyes', price = 15, starter_code = '{"html": "<div class=\\"eye left\\"></div>\\n<div class=\\"eye right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye {\\n  --eye-color: #2e221a;\\n  top: var(--eye-y, 30%);\\n}\\n\\n.eye.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye.right {\\n  left: calc(50% + 20px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻眼睛 3 × 3 格 */\\n.eye {\\n  position: absolute;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--eye-color);\\n}\\n\\n/* 右上角一格白色反光，眼睛看起來亮亮的 */\\n.eye::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '眼睛';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
