-- eyes：圓圓大眼
UPDATE parts SET category = 'html', slot = 'eyes', price = 15, starter_code = '{"html": "<div class=\\"eye-round left\\"><span class=\\"eye-round-pupil\\"></span></div>\\n<div class=\\"eye-round right\\"><span class=\\"eye-round-pupil\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-round {\\n  --eye-white: #fbf8f1;\\n  --pupil-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) - 4px);\\n}\\n\\n.eye-round.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-round.right {\\n  left: calc(50% + 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 白色的眼睛 4 × 4 格 */\\n.eye-round {\\n  position: absolute;\\n  width: 16px;\\n  height: 16px;\\n  background: var(--eye-white);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角會空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 眼珠 2 × 2 格，右上角一格白色反光 */\\n.eye-round-pupil {\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--pupil-color);\\n}\\n\\n.eye-round-pupil::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '圓圓大眼';
