-- eyes：瞇瞇眼
UPDATE parts SET category = 'css', slot = 'eyes', price = 15, starter_code = '{"html": "<div class=\\"eye-squint left\\"></div>\\n<div class=\\"eye-squint right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-squint {\\n  --eye-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) + 2px);\\n}\\n\\n.eye-squint.left {\\n  left: calc(50% - 26px);\\n}\\n\\n.eye-squint.right {\\n  left: calc(50% + 18px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 瞇起來的眼睛是 4 格排成一個彎彎的倒 V：上面兩格、下面左右各一格 */\\n/* 元素本身是上排左邊那一格，另外 3 格用 box-shadow 複製出來 */\\n.eye-squint {\\n  position: absolute;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--eye-color);\\n  box-shadow:\\n    4px 0 0 var(--eye-color),\\n    -4px 4px 0 var(--eye-color),\\n    8px 4px 0 var(--eye-color);\\n}", "js": ""}' WHERE name = '瞇瞇眼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
