-- eyes：星星眼
UPDATE parts SET category = 'html', slot = 'eyes', price = 20, starter_code = '{"html": "<div class=\\"eye-star left\\"></div>\\n<div class=\\"eye-star right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-star {\\n  --star-color: #f2d16b;\\n  top: calc(var(--eye-y, 30%) - 2px);\\n}\\n\\n.eye-star.left {\\n  left: calc(50% - 30px);\\n}\\n\\n.eye-star.right {\\n  left: calc(50% + 22px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 星星是 5 塊排成十字：元素本身是中間那塊，上下左右 4 塊用 box-shadow 複製出來 */\\n/* 每一塊 2 × 2 格（8px），所以 box-shadow 往旁邊移 8px */\\n.eye-star {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--star-color);\\n  box-shadow:\\n    0 -8px 0 var(--star-color),\\n    0 8px 0 var(--star-color),\\n    -8px 0 0 var(--star-color),\\n    8px 0 0 var(--star-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 中間一格白色反光 */\\n.eye-star::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '星星眼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '星星眼', 'html', 'eyes', 20, 'eyes.svg', '{"html": "<div class=\\"eye-star left\\"></div>\\n<div class=\\"eye-star right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-star {\\n  --star-color: #f2d16b;\\n  top: calc(var(--eye-y, 30%) - 2px);\\n}\\n\\n.eye-star.left {\\n  left: calc(50% - 30px);\\n}\\n\\n.eye-star.right {\\n  left: calc(50% + 22px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 星星是 5 塊排成十字：元素本身是中間那塊，上下左右 4 塊用 box-shadow 複製出來 */\\n/* 每一塊 2 × 2 格（8px），所以 box-shadow 往旁邊移 8px */\\n.eye-star {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--star-color);\\n  box-shadow:\\n    0 -8px 0 var(--star-color),\\n    0 8px 0 var(--star-color),\\n    -8px 0 0 var(--star-color),\\n    8px 0 0 var(--star-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 中間一格白色反光 */\\n.eye-star::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '星星眼');

-- eyes：愛心眼
UPDATE parts SET category = 'html', slot = 'eyes', price = 20, starter_code = '{"html": "<div class=\\"eye-heart left\\"></div>\\n<div class=\\"eye-heart right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-heart {\\n  --heart-color: #c8553d;\\n  top: calc(var(--eye-y, 30%) - 6px);\\n}\\n\\n.eye-heart.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.eye-heart.right {\\n  left: calc(50% + 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 愛心是 6 塊：上排左右各一塊、中間一排三塊、最下面一塊尖尖的 */\\n/* 元素本身是左上那一塊，另外 5 塊用 box-shadow 複製出來；每一塊 2 × 2 格（8px） */\\n.eye-heart {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--heart-color);\\n  box-shadow:\\n    16px 0 0 var(--heart-color),\\n    0 8px 0 var(--heart-color),\\n    8px 8px 0 var(--heart-color),\\n    16px 8px 0 var(--heart-color),\\n    8px 16px 0 var(--heart-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 左上那塊放一格白色反光 */\\n.eye-heart::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '愛心眼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '愛心眼', 'html', 'eyes', 20, 'eyes.svg', '{"html": "<div class=\\"eye-heart left\\"></div>\\n<div class=\\"eye-heart right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-heart {\\n  --heart-color: #c8553d;\\n  top: calc(var(--eye-y, 30%) - 6px);\\n}\\n\\n.eye-heart.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.eye-heart.right {\\n  left: calc(50% + 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 愛心是 6 塊：上排左右各一塊、中間一排三塊、最下面一塊尖尖的 */\\n/* 元素本身是左上那一塊，另外 5 塊用 box-shadow 複製出來；每一塊 2 × 2 格（8px） */\\n.eye-heart {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--heart-color);\\n  box-shadow:\\n    16px 0 0 var(--heart-color),\\n    0 8px 0 var(--heart-color),\\n    8px 8px 0 var(--heart-color),\\n    16px 8px 0 var(--heart-color),\\n    8px 16px 0 var(--heart-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 左上那塊放一格白色反光 */\\n.eye-heart::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '愛心眼');

-- eyes：墨鏡
UPDATE parts SET category = 'html', slot = 'eyes', price = 25, starter_code = '{"html": "<div class=\\"eye-shades\\">\\n  <span class=\\"eye-shades-lens left\\"></span>\\n  <span class=\\"eye-shades-lens right\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-shades {\\n  --lens-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) - 6px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 寬度是身體的 67%，鏡片和鼻樑也用百分比，跟著身體變寬變窄 */\\n.eye-shades {\\n  position: absolute;\\n  left: 16.5%;\\n  width: 67%;\\n  height: 20px;\\n}\\n\\n/* 鼻樑 */\\n.eye-shades::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 32%;\\n  width: 36%;\\n  height: 4px;\\n  background: var(--lens-color);\\n}\\n\\n/* 鏡片 3 格高，下面再接一排左右各縮一格的，鏡片底部就一階一階收窄 */\\n.eye-shades-lens {\\n  position: absolute;\\n  top: 0;\\n  width: 38%;\\n  height: 12px;\\n  background: var(--lens-color);\\n}\\n\\n.eye-shades-lens.left {\\n  left: 0;\\n}\\n\\n.eye-shades-lens.right {\\n  right: 0;\\n}\\n\\n.eye-shades-lens::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 12px;\\n  left: 4px;\\n  right: 4px;\\n  height: 4px;\\n  background: var(--lens-color);\\n}\\n\\n/* 鏡片上一格白色反光 */\\n.eye-shades-lens::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '墨鏡';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '墨鏡', 'html', 'eyes', 25, 'eyes.svg', '{"html": "<div class=\\"eye-shades\\">\\n  <span class=\\"eye-shades-lens left\\"></span>\\n  <span class=\\"eye-shades-lens right\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-shades {\\n  --lens-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) - 6px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 寬度是身體的 67%，鏡片和鼻樑也用百分比，跟著身體變寬變窄 */\\n.eye-shades {\\n  position: absolute;\\n  left: 16.5%;\\n  width: 67%;\\n  height: 20px;\\n}\\n\\n/* 鼻樑 */\\n.eye-shades::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 32%;\\n  width: 36%;\\n  height: 4px;\\n  background: var(--lens-color);\\n}\\n\\n/* 鏡片 3 格高，下面再接一排左右各縮一格的，鏡片底部就一階一階收窄 */\\n.eye-shades-lens {\\n  position: absolute;\\n  top: 0;\\n  width: 38%;\\n  height: 12px;\\n  background: var(--lens-color);\\n}\\n\\n.eye-shades-lens.left {\\n  left: 0;\\n}\\n\\n.eye-shades-lens.right {\\n  right: 0;\\n}\\n\\n.eye-shades-lens::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 12px;\\n  left: 4px;\\n  right: 4px;\\n  height: 4px;\\n  background: var(--lens-color);\\n}\\n\\n/* 鏡片上一格白色反光 */\\n.eye-shades-lens::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '墨鏡');

-- eyes：會眨眼
UPDATE parts SET category = 'css', slot = 'eyes', price = 30, starter_code = '{"html": "<div class=\\"eye-blink left\\"></div>\\n<div class=\\"eye-blink right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-blink {\\n  --eye-color: #2e221a;\\n  top: var(--eye-y, 30%);\\n}\\n\\n.eye-blink.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-blink.right {\\n  left: calc(50% + 20px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻眼睛 3 × 3 格，大部分時間睜開，96% 那一下壓扁就是眨眼 */\\n.eye-blink {\\n  position: absolute;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--eye-color);\\n  animation: eye-blink 3s infinite;\\n}\\n\\n/* 右上角一格白色反光 */\\n.eye-blink::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}\\n\\n@keyframes eye-blink {\\n  0%,\\n  92%,\\n  100% {\\n    transform: scaleY(1);\\n  }\\n  96% {\\n    transform: scaleY(0.1);\\n  }\\n}", "js": ""}' WHERE name = '會眨眼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會眨眼', 'css', 'eyes', 30, 'eyes.svg', '{"html": "<div class=\\"eye-blink left\\"></div>\\n<div class=\\"eye-blink right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-blink {\\n  --eye-color: #2e221a;\\n  top: var(--eye-y, 30%);\\n}\\n\\n.eye-blink.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-blink.right {\\n  left: calc(50% + 20px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻眼睛 3 × 3 格，大部分時間睜開，96% 那一下壓扁就是眨眼 */\\n.eye-blink {\\n  position: absolute;\\n  width: 12px;\\n  height: 12px;\\n  background: var(--eye-color);\\n  animation: eye-blink 3s infinite;\\n}\\n\\n/* 右上角一格白色反光 */\\n.eye-blink::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}\\n\\n@keyframes eye-blink {\\n  0%,\\n  92%,\\n  100% {\\n    transform: scaleY(1);\\n  }\\n  96% {\\n    transform: scaleY(0.1);\\n  }\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會眨眼');

-- eyes：跟著滑鼠的眼睛
UPDATE parts SET category = 'js', slot = 'eyes', price = 70, starter_code = '{"html": "<div class=\\"eye-follow left\\"><span class=\\"eye-follow-pupil\\"></span></div>\\n<div class=\\"eye-follow right\\"><span class=\\"eye-follow-pupil\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-follow {\\n  --eye-white: #fbf8f1;\\n  --pupil-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) - 4px);\\n}\\n\\n.eye-follow.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-follow.right {\\n  left: calc(50% + 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 白色的眼睛 4 × 4 格 */\\n.eye-follow {\\n  position: absolute;\\n  width: 16px;\\n  height: 16px;\\n  background: var(--eye-white);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角會空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 眼珠 2 × 2 格，放在正中間；JS 會讓它往滑鼠的方向移一格 */\\n.eye-follow-pupil {\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--pupil-color);\\n}\\n\\n.eye-follow-pupil::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": "// 算出滑鼠在眼睛的哪個方向，眼珠往那邊移一格（4px），一格一格動才有像素的感覺\\nconst followEyes = document.querySelectorAll(\'.eye-follow\')\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  followEyes.forEach((eye) => {\\n    const rect = eye.getBoundingClientRect()\\n    const angle = Math.atan2(\\n      e.clientY - (rect.top + rect.height / 2),\\n      e.clientX - (rect.left + rect.width / 2),\\n    )\\n    const x = Math.round(Math.cos(angle)) * 4\\n    const y = Math.round(Math.sin(angle)) * 4\\n    const pupil = eye.querySelector(\'.eye-follow-pupil\')\\n    pupil.style.transform = `translate(${x}px, ${y}px)`\\n  })\\n})"}' WHERE name = '跟著滑鼠的眼睛';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '跟著滑鼠的眼睛', 'js', 'eyes', 70, 'eyes.svg', '{"html": "<div class=\\"eye-follow left\\"><span class=\\"eye-follow-pupil\\"></span></div>\\n<div class=\\"eye-follow right\\"><span class=\\"eye-follow-pupil\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.eye-follow {\\n  --eye-white: #fbf8f1;\\n  --pupil-color: #2e221a;\\n  top: calc(var(--eye-y, 30%) - 4px);\\n}\\n\\n.eye-follow.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-follow.right {\\n  left: calc(50% + 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 白色的眼睛 4 × 4 格 */\\n.eye-follow {\\n  position: absolute;\\n  width: 16px;\\n  height: 16px;\\n  background: var(--eye-white);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角會空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 眼珠 2 × 2 格，放在正中間；JS 會讓它往滑鼠的方向移一格 */\\n.eye-follow-pupil {\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--pupil-color);\\n}\\n\\n.eye-follow-pupil::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": "// 算出滑鼠在眼睛的哪個方向，眼珠往那邊移一格（4px），一格一格動才有像素的感覺\\nconst followEyes = document.querySelectorAll(\'.eye-follow\')\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  followEyes.forEach((eye) => {\\n    const rect = eye.getBoundingClientRect()\\n    const angle = Math.atan2(\\n      e.clientY - (rect.top + rect.height / 2),\\n      e.clientX - (rect.left + rect.width / 2),\\n    )\\n    const x = Math.round(Math.cos(angle)) * 4\\n    const y = Math.round(Math.sin(angle)) * 4\\n    const pupil = eye.querySelector(\'.eye-follow-pupil\')\\n    pupil.style.transform = `translate(${x}px, ${y}px)`\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '跟著滑鼠的眼睛');

-- mouth：牙齒
UPDATE parts SET category = 'html', slot = 'mouth', price = 15, starter_code = '{"html": "<div class=\\"tooth left\\"></div>\\n<div class=\\"tooth right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tooth {\\n  --tooth-color: #fbf8f1;\\n  top: calc(var(--mouth-y, 60%) + 6px);\\n}\\n\\n.tooth.left {\\n  left: calc(50% - 18px);\\n}\\n\\n.tooth.right {\\n  left: calc(50% + 6px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每顆牙齒是 4 格：上面一排 3 格、下面中間 1 格尖尖的 */\\n/* 元素本身是左上那一格，另外 3 格用 box-shadow 複製出來 */\\n/* box-shadow 的前兩個數字是往右、往下移多少，移 4px 就是旁邊那一格 */\\n.tooth {\\n  position: absolute;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--tooth-color);\\n  box-shadow:\\n    4px 0 0 var(--tooth-color),\\n    8px 0 0 var(--tooth-color),\\n    4px 4px 0 var(--tooth-color);\\n}", "js": ""}' WHERE name = '牙齒';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
