SELECT '大嘴巴', 'html', 'mouth', 15, 'mouth.svg', '{"html": "<div class=\\"mouth-big\\"><span class=\\"mouth-big-tongue\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-big {\\n  --mouth-color: #2e221a;\\n  --tongue-color: #e8a0a0;\\n  top: calc(var(--mouth-y, 60%) - 4px);\\n  left: calc(50% - 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 張開的嘴 8 × 3 格，下面再接一排左右各縮一格的，嘴巴底部一階一階收圓 */\\n.mouth-big {\\n  position: absolute;\\n  width: 32px;\\n  height: 12px;\\n  background: var(--mouth-color);\\n}\\n\\n.mouth-big::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 12px;\\n  left: 4px;\\n  right: 4px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n/* 舌頭 4 × 2 格，放在嘴巴下半部 */\\n.mouth-big-tongue {\\n  position: absolute;\\n  top: 8px;\\n  left: 8px;\\n  width: 16px;\\n  height: 8px;\\n  background: var(--tongue-color);\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '大嘴巴');

