SELECT '吐舌頭', 'html', 'mouth', 15, 'mouth.svg', '{"html": "<div class=\\"mouth-tongue\\"><span class=\\"mouth-tongue-tip\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-tongue {\\n  --mouth-color: #2e221a;\\n  --tongue-color: #e8a0a0;\\n  top: calc(var(--mouth-y, 60%) + 4px);\\n  left: calc(50% - 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一條 8 格長的嘴巴線 */\\n.mouth-tongue {\\n  position: absolute;\\n  width: 32px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n/* 舌頭從嘴巴中間吐出來：2 × 2 格，外框沒有上邊，跟嘴巴線連在一起 */\\n.mouth-tongue-tip {\\n  position: absolute;\\n  top: 4px;\\n  left: 8px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--tongue-color);\\n  border: 4px solid #4a3426;\\n  border-top: 0;\\n}", "js": ""}'
