-- mouth：鳥嘴
UPDATE parts SET category = 'css', slot = 'mouth', price = 15, starter_code = '{"html": "<div class=\\"mouth-beak\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-beak {\\n  --beak-color: #e8a33d;\\n  top: calc(var(--mouth-y, 60%) - 4px);\\n  left: calc(50% - 12px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 鳥嘴三排，由上往下寬 6 格、4 格、2 格，一階一階變尖 */\\n.mouth-beak {\\n  position: absolute;\\n  width: 24px;\\n  height: 4px;\\n  background: var(--beak-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.mouth-beak::before,\\n.mouth-beak::after {\\n  content: \'\';\\n  position: absolute;\\n  height: 4px;\\n  background: var(--beak-color);\\n}\\n\\n.mouth-beak::before {\\n  top: 4px;\\n  left: 4px;\\n  width: 16px;\\n}\\n\\n.mouth-beak::after {\\n  top: 8px;\\n  left: 8px;\\n  width: 8px;\\n}", "js": ""}' WHERE name = '鳥嘴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '鳥嘴', 'css', 'mouth', 15, 'mouth.svg', '{"html": "<div class=\\"mouth-beak\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-beak {\\n  --beak-color: #e8a33d;\\n  top: calc(var(--mouth-y, 60%) - 4px);\\n  left: calc(50% - 12px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 鳥嘴三排，由上往下寬 6 格、4 格、2 格，一階一階變尖 */\\n.mouth-beak {\\n  position: absolute;\\n  width: 24px;\\n  height: 4px;\\n  background: var(--beak-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.mouth-beak::before,\\n.mouth-beak::after {\\n  content: \'\';\\n  position: absolute;\\n  height: 4px;\\n  background: var(--beak-color);\\n}\\n\\n.mouth-beak::before {\\n  top: 4px;\\n  left: 4px;\\n  width: 16px;\\n}\\n\\n.mouth-beak::after {\\n  top: 8px;\\n  left: 8px;\\n  width: 8px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '鳥嘴');

-- mouth：吸血鬼牙
UPDATE parts SET category = 'html', slot = 'mouth', price = 20, starter_code = '{"html": "<div class=\\"mouth-vampire\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-vampire {\\n  --mouth-color: #2e221a;\\n  --fang-color: #fbf8f1;\\n  top: calc(var(--mouth-y, 60%) + 2px);\\n  left: calc(50% - 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一條 8 格長的嘴巴線，兩顆尖牙用 ::before ::after 畫，每顆 1 格寬、2 格長 */\\n.mouth-vampire {\\n  position: absolute;\\n  width: 32px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n.mouth-vampire::before,\\n.mouth-vampire::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--fang-color);\\n}\\n\\n.mouth-vampire::before {\\n  left: 4px;\\n}\\n\\n.mouth-vampire::after {\\n  right: 4px;\\n}", "js": ""}' WHERE name = '吸血鬼牙';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '吸血鬼牙', 'html', 'mouth', 20, 'mouth.svg', '{"html": "<div class=\\"mouth-vampire\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-vampire {\\n  --mouth-color: #2e221a;\\n  --fang-color: #fbf8f1;\\n  top: calc(var(--mouth-y, 60%) + 2px);\\n  left: calc(50% - 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一條 8 格長的嘴巴線，兩顆尖牙用 ::before ::after 畫，每顆 1 格寬、2 格長 */\\n.mouth-vampire {\\n  position: absolute;\\n  width: 32px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n.mouth-vampire::before,\\n.mouth-vampire::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--fang-color);\\n}\\n\\n.mouth-vampire::before {\\n  left: 4px;\\n}\\n\\n.mouth-vampire::after {\\n  right: 4px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '吸血鬼牙');

-- mouth：鬍鬚
UPDATE parts SET category = 'html', slot = 'mouth', price = 20, starter_code = '{"html": "<div class=\\"mouth-whisker left\\"><span></span><span></span><span></span></div>\\n<div class=\\"mouth-whisker right\\"><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-whisker {\\n  --whisker-color: #2e221a;\\n  top: calc(var(--mouth-y, 60%) - 8px);\\n}\\n\\n/* 從身體左右邊緣往內 30px 長出來，露在外面 10px，身體變寬變窄都一樣 */\\n.mouth-whisker.left {\\n  left: -10px;\\n}\\n\\n.mouth-whisker.right {\\n  left: calc(100% - 30px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每邊三根鬍鬚，一根 1 格粗；上下兩根短一點，看起來有遠近 */\\n.mouth-whisker {\\n  position: absolute;\\n  width: 40px;\\n}\\n\\n.mouth-whisker span {\\n  display: block;\\n  width: 100%;\\n  height: 4px;\\n  margin-bottom: 4px;\\n  background: var(--whisker-color);\\n}\\n\\n.mouth-whisker span:first-child,\\n.mouth-whisker span:last-child {\\n  width: 75%;\\n}\\n\\n/* 右邊那組靠右對齊，短的鬍鬚才會在外側 */\\n.mouth-whisker.right span {\\n  margin-left: auto;\\n}", "js": ""}' WHERE name = '鬍鬚';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '鬍鬚', 'html', 'mouth', 20, 'mouth.svg', '{"html": "<div class=\\"mouth-whisker left\\"><span></span><span></span><span></span></div>\\n<div class=\\"mouth-whisker right\\"><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-whisker {\\n  --whisker-color: #2e221a;\\n  top: calc(var(--mouth-y, 60%) - 8px);\\n}\\n\\n/* 從身體左右邊緣往內 30px 長出來，露在外面 10px，身體變寬變窄都一樣 */\\n.mouth-whisker.left {\\n  left: -10px;\\n}\\n\\n.mouth-whisker.right {\\n  left: calc(100% - 30px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每邊三根鬍鬚，一根 1 格粗；上下兩根短一點，看起來有遠近 */\\n.mouth-whisker {\\n  position: absolute;\\n  width: 40px;\\n}\\n\\n.mouth-whisker span {\\n  display: block;\\n  width: 100%;\\n  height: 4px;\\n  margin-bottom: 4px;\\n  background: var(--whisker-color);\\n}\\n\\n.mouth-whisker span:first-child,\\n.mouth-whisker span:last-child {\\n  width: 75%;\\n}\\n\\n/* 右邊那組靠右對齊，短的鬍鬚才會在外側 */\\n.mouth-whisker.right span {\\n  margin-left: auto;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '鬍鬚');

-- mouth：O 型嘴
UPDATE parts SET category = 'css', slot = 'mouth', price = 10, starter_code = '{"html": "<div class=\\"mouth-o\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-o {\\n  --mouth-inside: #c8553d;\\n  top: calc(var(--mouth-y, 60%) + 4px);\\n  left: calc(50% - 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 嘴巴裡面 2 × 2 格，外框用 box-shadow 往上下左右各複製一次，四個角空出來就是圓圓的 O */\\n.mouth-o {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--mouth-inside);\\n  box-shadow:\\n    0 -4px 0 #2e221a,\\n    0 4px 0 #2e221a,\\n    -4px 0 0 #2e221a,\\n    4px 0 0 #2e221a;\\n}", "js": ""}' WHERE name = 'O 型嘴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT 'O 型嘴', 'css', 'mouth', 10, 'mouth.svg', '{"html": "<div class=\\"mouth-o\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-o {\\n  --mouth-inside: #c8553d;\\n  top: calc(var(--mouth-y, 60%) + 4px);\\n  left: calc(50% - 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 嘴巴裡面 2 × 2 格，外框用 box-shadow 往上下左右各複製一次，四個角空出來就是圓圓的 O */\\n.mouth-o {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--mouth-inside);\\n  box-shadow:\\n    0 -4px 0 #2e221a,\\n    0 4px 0 #2e221a,\\n    -4px 0 0 #2e221a,\\n    4px 0 0 #2e221a;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = 'O 型嘴');

-- mouth：會說話的嘴
UPDATE parts SET category = 'js', slot = 'mouth', price = 60, starter_code = '{"html": "<div class=\\"mouth-talk\\"></div>\\n<div class=\\"mouth-bubble\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-talk {\\n  --mouth-color: #2e221a;\\n  top: calc(var(--mouth-y, 60%) + 4px);\\n  left: calc(50% - 12px);\\n}\\n\\n.mouth-bubble {\\n  top: calc(var(--horn-y, 0%) - 50px);\\n  left: calc(50% + 30px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n.body {\\n  cursor: pointer;\\n}\\n\\n/* 嘴巴 6 格長、1 格高；說話的時候在 1 格和 3 格之間一格一格跳 */\\n.mouth-talk {\\n  position: absolute;\\n  width: 24px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n.mouth-talk.talking {\\n  animation: mouth-talk 0.3s steps(2) infinite alternate;\\n}\\n\\n@keyframes mouth-talk {\\n  to {\\n    height: 12px;\\n  }\\n}\\n\\n/* 說話泡泡：直角、4px 外框，跟像素圖一樣 */\\n.mouth-bubble {\\n  position: absolute;\\n  padding: 4px 8px;\\n  background: #fbf8f1;\\n  border: 4px solid #4a3426;\\n  font-size: 14px;\\n  white-space: nowrap;\\n  opacity: 0;\\n  transition: opacity 0.2s;\\n}\\n\\n.mouth-bubble.show {\\n  opacity: 1;\\n}", "js": "// 點身體隨機說一句話，兩秒後收起來\\nconst talkBody = document.querySelector(\'.body\')\\nconst talkMouth = document.querySelector(\'.mouth-talk\')\\nconst talkBubble = document.querySelector(\'.mouth-bubble\')\\nconst talkLines = [\'你好！\', \'肚子餓了\', \'我是合成獸\', \'再點我一下\', \'今天也要寫程式\']\\nlet talkTimer\\ntalkBody.addEventListener(\'click\', () => {\\n  talkBubble.textContent = talkLines[Math.floor(Math.random() * talkLines.length)]\\n  talkBubble.classList.add(\'show\')\\n  talkMouth.classList.add(\'talking\')\\n  clearTimeout(talkTimer)\\n  talkTimer = setTimeout(() => {\\n    talkBubble.classList.remove(\'show\')\\n    talkMouth.classList.remove(\'talking\')\\n  }, 2000)\\n})"}' WHERE name = '會說話的嘴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會說話的嘴', 'js', 'mouth', 60, 'mouth.svg', '{"html": "<div class=\\"mouth-talk\\"></div>\\n<div class=\\"mouth-bubble\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.mouth-talk {\\n  --mouth-color: #2e221a;\\n  top: calc(var(--mouth-y, 60%) + 4px);\\n  left: calc(50% - 12px);\\n}\\n\\n.mouth-bubble {\\n  top: calc(var(--horn-y, 0%) - 50px);\\n  left: calc(50% + 30px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n.body {\\n  cursor: pointer;\\n}\\n\\n/* 嘴巴 6 格長、1 格高；說話的時候在 1 格和 3 格之間一格一格跳 */\\n.mouth-talk {\\n  position: absolute;\\n  width: 24px;\\n  height: 4px;\\n  background: var(--mouth-color);\\n}\\n\\n.mouth-talk.talking {\\n  animation: mouth-talk 0.3s steps(2) infinite alternate;\\n}\\n\\n@keyframes mouth-talk {\\n  to {\\n    height: 12px;\\n  }\\n}\\n\\n/* 說話泡泡：直角、4px 外框，跟像素圖一樣 */\\n.mouth-bubble {\\n  position: absolute;\\n  padding: 4px 8px;\\n  background: #fbf8f1;\\n  border: 4px solid #4a3426;\\n  font-size: 14px;\\n  white-space: nowrap;\\n  opacity: 0;\\n  transition: opacity 0.2s;\\n}\\n\\n.mouth-bubble.show {\\n  opacity: 1;\\n}", "js": "// 點身體隨機說一句話，兩秒後收起來\\nconst talkBody = document.querySelector(\'.body\')\\nconst talkMouth = document.querySelector(\'.mouth-talk\')\\nconst talkBubble = document.querySelector(\'.mouth-bubble\')\\nconst talkLines = [\'你好！\', \'肚子餓了\', \'我是合成獸\', \'再點我一下\', \'今天也要寫程式\']\\nlet talkTimer\\ntalkBody.addEventListener(\'click\', () => {\\n  talkBubble.textContent = talkLines[Math.floor(Math.random() * talkLines.length)]\\n  talkBubble.classList.add(\'show\')\\n  talkMouth.classList.add(\'talking\')\\n  clearTimeout(talkTimer)\\n  talkTimer = setTimeout(() => {\\n    talkBubble.classList.remove(\'show\')\\n    talkMouth.classList.remove(\'talking\')\\n  }, 2000)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會說話的嘴');

-- pattern：毛色
UPDATE parts SET category = 'css', slot = 'pattern', price = 20, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：--fur-color 是底色，最後的 15% 是條紋的深淺 */\\n.body {\\n  --fur-color: #e8a33d;\\n  --stripe-color: rgb(46 34 26 / 15%);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 直的條紋：每 6 格一個循環，前 4 格空白、後 2 格是條紋，邊緣是直的，跟像素圖一樣 */\\n.body {\\n  background-image: repeating-linear-gradient(\\n    90deg,\\n    transparent 0 16px,\\n    var(--stripe-color) 16px 24px\\n  );\\n}", "js": ""}' WHERE name = '毛色';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '毛色', 'css', 'pattern', 20, 'pattern.svg', '{"html": "", "css": "/* 想換顏色，改這裡就好：--fur-color 是底色，最後的 15% 是條紋的深淺 */\\n.body {\\n  --fur-color: #e8a33d;\\n  --stripe-color: rgb(46 34 26 / 15%);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 直的條紋：每 6 格一個循環，前 4 格空白、後 2 格是條紋，邊緣是直的，跟像素圖一樣 */\\n.body {\\n  background-image: repeating-linear-gradient(\\n    90deg,\\n    transparent 0 16px,\\n    var(--stripe-color) 16px 24px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '毛色');

-- pattern：點點
UPDATE parts SET category = 'css', slot = 'pattern', price = 20, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：點點是 --dot-color，點點以外的地方是身體的 --fur-color */\\n.body {\\n  --dot-color: #fbf8f1;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 方方的像素點點：每 16px（4 × 4 格）一個循環，右上角 8px（2 × 2 格）是點點 */\\n/* conic-gradient 從 12 點鐘方向順時針畫，前 25% 剛好是右上角那一塊 */\\n/* 改 background-size 調點點的間距，用 4 的倍數才會對齊像素格子 */\\n.body {\\n  background-image: conic-gradient(var(--dot-color) 25%, transparent 0);\\n  background-size: 16px 16px;\\n}", "js": ""}' WHERE name = '點點';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '點點', 'css', 'pattern', 20, 'pattern.svg', '{"html": "", "css": "/* 想換顏色，改這裡就好：點點是 --dot-color，點點以外的地方是身體的 --fur-color */\\n.body {\\n  --dot-color: #fbf8f1;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 方方的像素點點：每 16px（4 × 4 格）一個循環，右上角 8px（2 × 2 格）是點點 */\\n/* conic-gradient 從 12 點鐘方向順時針畫，前 25% 剛好是右上角那一塊 */\\n/* 改 background-size 調點點的間距，用 4 的倍數才會對齊像素格子 */\\n.body {\\n  background-image: conic-gradient(var(--dot-color) 25%, transparent 0);\\n  background-size: 16px 16px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '點點');

-- pattern：格子
UPDATE parts SET category = 'css', slot = 'pattern', price = 20, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：一半的格子是 --check-color，另一半是身體的 --fur-color */\\n.body {\\n  --check-color: #e8e0d0;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 棋盤格：每 32px（8 × 8 格）一個循環，切成四塊，右上和左下塗 --check-color */\\n/* conic-gradient 從 12 點鐘方向順時針畫：0~25% 是右上、25~50% 右下、50~75% 左下、75~100% 左上 */\\n/* transparent 的那兩塊透出底下的 --fur-color */\\n.body {\\n  background-image: conic-gradient(\\n    var(--check-color) 0 25%,\\n    transparent 25% 50%,\\n    var(--check-color) 50% 75%,\\n    transparent 75%\\n  );\\n  background-size: 32px 32px;\\n}", "js": ""}' WHERE name = '格子';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '格子', 'css', 'pattern', 20, 'pattern.svg', '{"html": "", "css": "/* 想換顏色，改這裡就好：一半的格子是 --check-color，另一半是身體的 --fur-color */\\n.body {\\n  --check-color: #e8e0d0;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 棋盤格：每 32px（8 × 8 格）一個循環，切成四塊，右上和左下塗 --check-color */\\n/* conic-gradient 從 12 點鐘方向順時針畫：0~25% 是右上、25~50% 右下、50~75% 左下、75~100% 左上 */\\n/* transparent 的那兩塊透出底下的 --fur-color */\\n.body {\\n  background-image: conic-gradient(\\n    var(--check-color) 0 25%,\\n    transparent 25% 50%,\\n    var(--check-color) 50% 75%,\\n    transparent 75%\\n  );\\n  background-size: 32px 32px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '格子');

-- pattern：漸層
UPDATE parts SET category = 'css', slot = 'pattern', price = 25, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：上面疊亮色、下面疊暗色，看起來像有光從上面照下來 */\\n.body {\\n  --light-color: #fbf8f1;\\n  --dark-color: #2e221a;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 像素風的漸層：不讓顏色慢慢變，分成 5 段一段一段變暗，中間那段透出 --fur-color */\\n/* color-mix 把顏色調成半透明：45% 就是只疊上四成五的亮色 */\\n/* 每一段寫兩個位置（例如 20% 40%），同一段裡顏色一樣，邊緣就是直的 */\\n.body {\\n  background-image: linear-gradient(\\n    color-mix(in srgb, var(--light-color) 45%, transparent) 0 20%,\\n    color-mix(in srgb, var(--light-color) 20%, transparent) 20% 40%,\\n    transparent 40% 60%,\\n    color-mix(in srgb, var(--dark-color) 12%, transparent) 60% 80%,\\n    color-mix(in srgb, var(--dark-color) 25%, transparent) 80%\\n  );\\n}", "js": ""}' WHERE name = '漸層';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
