UPDATE parts SET category = 'css', slot = 'pattern', price = 25, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：--zebra-color 是條紋的顏色 */\\n.body {\\n  --zebra-color: #2e221a;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 下面是畫條紋的程式，想改形狀再研究 */\\n/* 一塊 32 × 24 的磁磚裡有兩小段 12px 寬的條紋：上面那段在左邊，下面那段往右挪 4px，排起來是鋸齒狀的直條紋 */\\n/* conic-gradient 從 270 度（左邊）開始畫 25%，剛好畫出 12px 12px 那個點左上角的方塊 */\\n.body {\\n  background-image:\\n    conic-gradient(from 270deg at 12px 12px, var(--zebra-color) 25%, transparent 0),\\n    conic-gradient(from 270deg at 12px 12px, var(--zebra-color) 25%, transparent 0);\\n  background-size: 32px 24px;\\n  background-position:\\n    0 0,\\n    4px 12px;\\n}", "js": ""}' WHERE name = '斑馬紋';
