-- pattern：星空
UPDATE parts SET category = 'css', slot = 'pattern', price = 30, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：--star-color 是星星，--sky-top 和 --sky-bottom 是夜空上下兩段的顏色 */\\n.body {\\n  --star-color: #fbf8f1;\\n  --sky-top: #1d2b53;\\n  --sky-bottom: #3b3f7a;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 兩層方方的星星（一格 4px），間距不一樣、錯開放，最下面一層是上下兩段的夜空 */\\n/* conic-gradient 最後 25% 是左上角，在 4px 4px 的位置轉，剛好畫出一格 4px 的方塊 */\\n.body {\\n  background-image:\\n    conic-gradient(at 4px 4px, transparent 75%, var(--star-color) 0),\\n    conic-gradient(at 4px 4px, transparent 75%, var(--star-color) 0),\\n    linear-gradient(var(--sky-top) 50%, var(--sky-bottom) 50%);\\n  background-size:\\n    28px 28px,\\n    20px 20px,\\n    100% 100%;\\n  background-position:\\n    4px 4px,\\n    12px 16px,\\n    0 0;\\n}", "js": ""}' WHERE name = '星空';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
