-- pattern：白肚子
UPDATE parts SET category = 'css', slot = 'pattern', price = 20, starter_code = '{"html": "", "css": "/* 想換顏色，改這裡就好：--belly-color 是肚子的顏色 */\\n.body {\\n  --belly-color: #fbf8f1;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 三塊一樣顏色的長方形疊成一個階梯狀的橢圓，中心都在身體下緣往上 32px 的地方 */\\n/* linear-gradient 頭尾同一個顏色就是一塊色塊，用 background-size 決定色塊多大 */\\n.body {\\n  background-image:\\n    linear-gradient(var(--belly-color), var(--belly-color)),\\n    linear-gradient(var(--belly-color), var(--belly-color)),\\n    linear-gradient(var(--belly-color), var(--belly-color));\\n  background-size:\\n    40px 40px,\\n    56px 32px,\\n    64px 24px;\\n  background-position:\\n    50% calc(100% - 12px),\\n    50% calc(100% - 16px),\\n    50% calc(100% - 20px);\\n  background-repeat: no-repeat;\\n}", "js": ""}' WHERE name = '白肚子';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
