-- pattern：點一下換毛色
UPDATE parts SET category = 'js', slot = 'pattern', price = 50, starter_code = '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: background-color 0.3s;\\n}", "js": "// 點身體把 --fur-color 換成隨機顏色\\nconst furBody = document.querySelector(\'.body\')\\nfurBody.addEventListener(\'click\', () => {\\n  const hue = Math.floor(Math.random() * 360)\\n  furBody.style.setProperty(\'--fur-color\', `hsl(${hue}, 55%, 65%)`)\\n})"}' WHERE name = '點一下換毛色';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '點一下換毛色', 'js', 'pattern', 50, 'pattern.svg', '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: background-color 0.3s;\\n}", "js": "// 點身體把 --fur-color 換成隨機顏色\\nconst furBody = document.querySelector(\'.body\')\\nfurBody.addEventListener(\'click\', () => {\\n  const hue = Math.floor(Math.random() * 360)\\n  furBody.style.setProperty(\'--fur-color\', `hsl(${hue}, 55%, 65%)`)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '點一下換毛色');

-- wings：翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 30, starter_code = '{"html": "<div class=\\"wing left\\"></div>\\n<div class=\\"wing right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing {\\n  --wing-color: #5a9a4a;\\n  --vein-color: #2e221a;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing.left {\\n  left: calc(-66px + var(--wing-x, 0px));\\n}\\n\\n.wing.right {\\n  left: calc(100% + 2px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一對葉子翅膀，每片 16 × 9 格，尖端朝外；z-index: -2 排在身體後面 */\\n/* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n.wing {\\n  position: absolute;\\n  z-index: -2;\\n  width: 64px;\\n  height: 36px;\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 葉子本體，中間一條 1 格粗的葉脈 */\\n.wing::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background:\\n    linear-gradient(transparent 16px, var(--vein-color) 16px 20px, transparent 20px),\\n    var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 30%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing.left {\\n  --wing-shape: polygon(\\n    32px 0,\\n    64px 0,\\n    64px 36px,\\n    32px 36px,\\n    32px 32px,\\n    20px 32px,\\n    20px 28px,\\n    12px 28px,\\n    12px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px,\\n    0 16px,\\n    4px 16px,\\n    4px 12px,\\n    12px 12px,\\n    12px 8px,\\n    20px 8px,\\n    20px 4px,\\n    32px 4px\\n  );\\n}\\n\\n.wing.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    44px 4px,\\n    44px 8px,\\n    52px 8px,\\n    52px 12px,\\n    60px 12px,\\n    60px 16px,\\n    64px 16px,\\n    64px 20px,\\n    60px 20px,\\n    60px 24px,\\n    52px 24px,\\n    52px 28px,\\n    44px 28px,\\n    44px 32px,\\n    32px 32px,\\n    32px 36px,\\n    0 36px\\n  );\\n}", "js": ""}' WHERE name = '翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '翅膀', 'css', 'wings', 30, 'wings.svg', '{"html": "<div class=\\"wing left\\"></div>\\n<div class=\\"wing right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing {\\n  --wing-color: #5a9a4a;\\n  --vein-color: #2e221a;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing.left {\\n  left: calc(-66px + var(--wing-x, 0px));\\n}\\n\\n.wing.right {\\n  left: calc(100% + 2px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一對葉子翅膀，每片 16 × 9 格，尖端朝外；z-index: -2 排在身體後面 */\\n/* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n.wing {\\n  position: absolute;\\n  z-index: -2;\\n  width: 64px;\\n  height: 36px;\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n/* 葉子本體，中間一條 1 格粗的葉脈 */\\n.wing::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background:\\n    linear-gradient(transparent 16px, var(--vein-color) 16px 20px, transparent 20px),\\n    var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 30%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing.left {\\n  --wing-shape: polygon(\\n    32px 0,\\n    64px 0,\\n    64px 36px,\\n    32px 36px,\\n    32px 32px,\\n    20px 32px,\\n    20px 28px,\\n    12px 28px,\\n    12px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px,\\n    0 16px,\\n    4px 16px,\\n    4px 12px,\\n    12px 12px,\\n    12px 8px,\\n    20px 8px,\\n    20px 4px,\\n    32px 4px\\n  );\\n}\\n\\n.wing.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    44px 4px,\\n    44px 8px,\\n    52px 8px,\\n    52px 12px,\\n    60px 12px,\\n    60px 16px,\\n    64px 16px,\\n    64px 20px,\\n    60px 20px,\\n    60px 24px,\\n    52px 24px,\\n    52px 28px,\\n    44px 28px,\\n    44px 32px,\\n    32px 32px,\\n    32px 36px,\\n    0 36px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '翅膀');

-- wings：一對小翅膀
UPDATE parts SET category = 'html', slot = 'wings', price = 30, starter_code = '{"html": "<div class=\\"wing-pair left\\"></div>\\n<div class=\\"wing-pair right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-pair {\\n  --wing-color: #6b8fb0;\\n  top: calc(var(--wing-y, 10%) + 6px);\\n}\\n\\n.wing-pair.left {\\n  left: calc(-44px + var(--wing-x, 0px));\\n}\\n\\n.wing-pair.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 10 × 7 格 */\\n.wing-pair {\\n  position: absolute;\\n  z-index: -2;\\n  width: 40px;\\n  height: 28px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-pair::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-pair.left {\\n  --wing-shape: polygon(\\n    12px 0,\\n    40px 0,\\n    40px 20px,\\n    36px 20px,\\n    36px 24px,\\n    24px 24px,\\n    24px 28px,\\n    0 28px,\\n    0 8px,\\n    4px 8px,\\n    4px 4px,\\n    12px 4px\\n  );\\n}\\n\\n.wing-pair.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    28px 0,\\n    28px 4px,\\n    36px 4px,\\n    36px 8px,\\n    40px 8px,\\n    40px 28px,\\n    16px 28px,\\n    16px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px\\n  );\\n}", "js": ""}' WHERE name = '一對小翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
