FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '一對小翅膀');

-- wings：天使翅膀
UPDATE parts SET category = 'html', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-angel left\\"><span></span><span></span><span></span></div>\\n<div class=\\"wing-angel right\\"><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-angel {\\n  --feather-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) - 8px);\\n}\\n\\n.wing-angel.left {\\n  left: calc(-60px + var(--wing-x, 0px));\\n}\\n\\n.wing-angel.right {\\n  left: calc(100% - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 三片羽毛由長到短往下疊，長度 13、10、7 格；上下兩片共用一條外框，疊起來就是一階一階的翅膀 */\\n.wing-angel {\\n  position: absolute;\\n  z-index: -2;\\n  width: 60px;\\n  height: 40px;\\n}\\n\\n.wing-angel span {\\n  position: absolute;\\n  height: 8px;\\n  background: var(--feather-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 15%);\\n}\\n\\n.wing-angel span:nth-child(1) {\\n  top: 0;\\n  width: 52px;\\n}\\n\\n.wing-angel span:nth-child(2) {\\n  top: 12px;\\n  width: 40px;\\n}\\n\\n.wing-angel span:nth-child(3) {\\n  top: 24px;\\n  width: 28px;\\n}\\n\\n/* 羽毛貼著身體那一側對齊：左邊的翅膀靠右、右邊的翅膀靠左 */\\n.wing-angel.left span {\\n  right: 0;\\n}\\n\\n.wing-angel.right span {\\n  left: 0;\\n}", "js": ""}' WHERE name = '天使翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '天使翅膀', 'html', 'wings', 35, 'wings.svg', '{"html": "<div class=\\"wing-angel left\\"><span></span><span></span><span></span></div>\\n<div class=\\"wing-angel right\\"><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-angel {\\n  --feather-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) - 8px);\\n}\\n\\n.wing-angel.left {\\n  left: calc(-60px + var(--wing-x, 0px));\\n}\\n\\n.wing-angel.right {\\n  left: calc(100% - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 三片羽毛由長到短往下疊，長度 13、10、7 格；上下兩片共用一條外框，疊起來就是一階一階的翅膀 */\\n.wing-angel {\\n  position: absolute;\\n  z-index: -2;\\n  width: 60px;\\n  height: 40px;\\n}\\n\\n.wing-angel span {\\n  position: absolute;\\n  height: 8px;\\n  background: var(--feather-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 15%);\\n}\\n\\n.wing-angel span:nth-child(1) {\\n  top: 0;\\n  width: 52px;\\n}\\n\\n.wing-angel span:nth-child(2) {\\n  top: 12px;\\n  width: 40px;\\n}\\n\\n.wing-angel span:nth-child(3) {\\n  top: 24px;\\n  width: 28px;\\n}\\n\\n/* 羽毛貼著身體那一側對齊：左邊的翅膀靠右、右邊的翅膀靠左 */\\n.wing-angel.left span {\\n  right: 0;\\n}\\n\\n.wing-angel.right span {\\n  left: 0;\\n}", "js": ""}'
