UPDATE parts SET category = 'css', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-bat left\\"></div>\\n<div class=\\"wing-bat right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-bat {\\n  --wing-color: #6f6a64;\\n  top: calc(var(--wing-y, 10%) - 4px);\\n}\\n\\n.wing-bat.left {\\n  left: calc(-70px + var(--wing-x, 0px));\\n}\\n\\n.wing-bat.right {\\n  left: calc(100% - 2px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 18 × 11 格：上緣往外斜到翼尖，下緣三個尖角 */\\n.wing-bat {\\n  position: absolute;\\n  z-index: -2;\\n  width: 72px;\\n  height: 44px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-bat::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-bat.left {\\n  --wing-shape: polygon(\\n    0 0,\\n    8px 0,\\n    8px 4px,\\n    16px 4px,\\n    16px 8px,\\n    28px 8px,\\n    28px 12px,\\n    40px 12px,\\n    40px 16px,\\n    64px 16px,\\n    64px 12px,\\n    72px 12px,\\n    72px 44px,\\n    56px 44px,\\n    56px 40px,\\n    52px 40px,\\n    52px 36px,\\n    48px 36px,\\n    48px 32px,\\n    44px 32px,\\n    44px 36px,\\n    40px 36px,\\n    40px 40px,\\n    36px 40px,\\n    36px 44px,\\n    32px 44px,\\n    32px 40px,\\n    28px 40px,\\n    28px 36px,\\n    24px 36px,\\n    24px 32px,\\n    20px 32px,\\n    20px 36px,\\n    16px 36px,\\n    16px 40px,\\n    12px 40px,\\n    12px 44px,\\n    8px 44px,\\n    8px 36px,\\n    4px 36px,\\n    4px 28px,\\n    0 28px\\n  );\\n}\\n\\n.wing-bat.right {\\n  --wing-shape: polygon(\\n    64px 0,\\n    72px 0,\\n    72px 28px,\\n    68px 28px,\\n    68px 36px,\\n    64px 36px,\\n    64px 44px,\\n    60px 44px,\\n    60px 40px,\\n    56px 40px,\\n    56px 36px,\\n    52px 36px,\\n    52px 32px,\\n    48px 32px,\\n    48px 36px,\\n    44px 36px,\\n    44px 40px,\\n    40px 40px,\\n    40px 44px,\\n    36px 44px,\\n    36px 40px,\\n    32px 40px,\\n    32px 36px,\\n    28px 36px,\\n    28px 32px,\\n    24px 32px,\\n    24px 36px,\\n    20px 36px,\\n    20px 40px,\\n    16px 40px,\\n    16px 44px,\\n    0 44px,\\n    0 12px,\\n    8px 12px,\\n    8px 16px,\\n    32px 16px,\\n    32px 12px,\\n    44px 12px,\\n    44px 8px,\\n    56px 8px,\\n    56px 4px,\\n    64px 4px\\n  );\\n}", "js": ""}' WHERE name = '蝙蝠翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
