,\\n    64px 44px,\\n    60px 44px,\\n    60px 40px,\\n    56px 40px,\\n    56px 36px,\\n    52px 36px,\\n    52px 32px,\\n    48px 32px,\\n    48px 36px,\\n    44px 36px,\\n    44px 40px,\\n    40px 40px,\\n    40px 44px,\\n    36px 44px,\\n    36px 40px,\\n    32px 40px,\\n    32px 36px,\\n    28px 36px,\\n    28px 32px,\\n    24px 32px,\\n    24px 36px,\\n    20px 36px,\\n    20px 40px,\\n    16px 40px,\\n    16px 44px,\\n    0 44px,\\n    0 12px,\\n    8px 12px,\\n    8px 16px,\\n    32px 16px,\\n    32px 12px,\\n    44px 12px,\\n    44px 8px,\\n    56px 8px,\\n    56px 4px,\\n    64px 4px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '蝙蝠翅膀');

-- wings：蝴蝶翅膀
UPDATE parts SET category = 'html', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-butterfly left\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>\\n<div class=\\"wing-butterfly right\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-butterfly {\\n  --top-color: #e8a33d;\\n  --bottom-color: #e8a0a0;\\n  top: calc(var(--wing-y, 10%) - 12px);\\n}\\n\\n.wing-butterfly.left {\\n  left: calc(-48px + var(--wing-x, 0px));\\n}\\n\\n.wing-butterfly.right {\\n  left: calc(100% - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 上下兩片，上面大 10 × 8 格、下面小 7 × 6 格 */\\n.wing-butterfly {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 72px;\\n}\\n\\n.wing-butterfly span {\\n  position: absolute;\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n.wing-butterfly-top {\\n  top: 4px;\\n  width: 40px;\\n  height: 32px;\\n  background: var(--top-color);\\n}\\n\\n.wing-butterfly-bottom {\\n  top: 40px;\\n  width: 28px;\\n  height: 24px;\\n  background: var(--bottom-color);\\n}\\n\\n/* 上翅膀中間一個 2 × 2 格的白點 */\\n.wing-butterfly-top::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 12px;\\n  left: 16px;\\n  width: 8px;\\n  height: 8px;\\n  background: #fbf8f1;\\n}\\n\\n/* 兩片翅膀都貼著身體那一側：左邊的靠右、右邊的靠左 */\\n.wing-butterfly.left span {\\n  right: 4px;\\n}\\n\\n.wing-butterfly.right span {\\n  left: 4px;\\n}", "js": ""}' WHERE name = '蝴蝶翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '蝴蝶翅膀', 'html', 'wings', 35, 'wings.svg', '{"html": "<div class=\\"wing-butterfly left\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>\\n<div class=\\"wing-butterfly right\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-butterfly {\\n  --top-color: #e8a33d;\\n  --bottom-color: #e8a0a0;\\n  top: calc(var(--wing-y, 10%) - 12px);\\n}\\n\\n.wing-butterfly.left {\\n  left: calc(-48px + var(--wing-x, 0px));\\n}\\n\\n.wing-butterfly.right {\\n  left: calc(100% - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 上下兩片，上面大 10 × 8 格、下面小 7 × 6 格 */\\n.wing-butterfly {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 72px;\\n}\\n\\n.wing-butterfly span {\\n  position: absolute;\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n.wing-butterfly-top {\\n  top: 4px;\\n  width: 40px;\\n  height: 32px;\\n  background: var(--top-color);\\n}\\n\\n.wing-butterfly-bottom {\\n  top: 40px;\\n  width: 28px;\\n  height: 24px;\\n  background: var(--bottom-color);\\n}\\n\\n/* 上翅膀中間一個 2 × 2 格的白點 */\\n.wing-butterfly-top::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 12px;\\n  left: 16px;\\n  width: 8px;\\n  height: 8px;\\n  background: #fbf8f1;\\n}\\n\\n/* 兩片翅膀都貼著身體那一側：左邊的靠右、右邊的靠左 */\\n.wing-butterfly.left span {\\n  right: 4px;\\n}\\n\\n.wing-butterfly.right span {\\n  left: 4px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '蝴蝶翅膀');

-- wings：蜻蜓翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 30, starter_code = '{"html": "<div class=\\"wing-dragonfly left\\"></div>\\n<div class=\\"wing-dragonfly right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好；最後的 60% 是透明度 */\\n.wing-dragonfly {\\n  --wing-color: rgb(156 196 190 / 60%);\\n  top: var(--wing-y, 10%);\\n}\\n\\n.wing-dragonfly.left {\\n  left: calc(-84px + var(--wing-x, 0px));\\n}\\n\\n.wing-dragonfly.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 前翅 19 × 2 格，後翅用 ::after 畫在下面、短一點；半透明看得到後面 */\\n.wing-dragonfly,\\n.wing-dragonfly::after {\\n  position: absolute;\\n  z-index: -2;\\n  height: 8px;\\n  background: var(--wing-color);\\n  border: 4px solid rgb(74 52 38 / 60%);\\n}\\n\\n.wing-dragonfly {\\n  width: 76px;\\n}\\n\\n.wing-dragonfly::after {\\n  content: \'\';\\n  top: 16px;\\n  width: 60px;\\n}\\n\\n/* 後翅貼著身體那一側：左邊的靠右、右邊的靠左 */\\n.wing-dragonfly.left::after {\\n  right: -4px;\\n}\\n\\n.wing-dragonfly.right::after {\\n  left: -4px;\\n}", "js": ""}' WHERE name = '蜻蜓翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '蜻蜓翅膀', 'css', 'wings', 30, 'wings.svg', '{"html": "<div class=\\"wing-dragonfly left\\"></div>\\n<div class=\\"wing-dragonfly right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好；最後的 60% 是透明度 */\\n.wing-dragonfly {\\n  --wing-color: rgb(156 196 190 / 60%);\\n  top: var(--wing-y, 10%);\\n}\\n\\n.wing-dragonfly.left {\\n  left: calc(-84px + var(--wing-x, 0px));\\n}\\n\\n.wing-dragonfly.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 前翅 19 × 2 格，後翅用 ::after 畫在下面、短一點；半透明看得到後面 */\\n.wing-dragonfly,\\n.wing-dragonfly::after {\\n  position: absolute;\\n  z-index: -2;\\n  height: 8px;\\n  background: var(--wing-color);\\n  border: 4px solid rgb(74 52 38 / 60%);\\n}\\n\\n.wing-dragonfly {\\n  width: 76px;\\n}\\n\\n.wing-dragonfly::after {\\n  content: \'\';\\n  top: 16px;\\n  width: 60px;\\n}\\n\\n/* 後翅貼著身體那一側：左邊的靠右、右邊的靠左 */\\n.wing-dragonfly.left::after {\\n  right: -4px;\\n}\\n\\n.wing-dragonfly.right::after {\\n  left: -4px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '蜻蜓翅膀');

-- wings：龍翼
UPDATE parts SET category = 'css', slot = 'wings', price = 40, starter_code = '{"html": "<div class=\\"wing-dragon left\\"><span></span></div>\\n<div class=\\"wing-dragon right\\"><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-dragon {\\n  --wing-color: #5a9a4a;\\n  top: calc(var(--wing-y, 10%) - 24px);\\n}\\n\\n.wing-dragon.left {\\n  left: calc(-104px + var(--wing-x, 0px));\\n}\\n\\n.wing-dragon.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 25 × 20 格：上緣是骨架往外伸，下緣三個大尖角 */\\n.wing-dragon {\\n  position: absolute;\\n  z-index: -2;\\n  width: 100px;\\n  height: 80px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-dragon span {\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-dragon.left {\\n  --wing-shape: polygon(\\n    4px 0,\\n    16px 0,\\n    16px 4px,\\n    28px 4px,\\n    28px 8px,\\n    44px 8px,\\n    44px 12px,\\n    64px 12px,\\n    64px 16px,\\n    80px 16px,\\n    80px 20px,\\n    100px 20px,\\n    100px 80px,\\n    92px 80px,\\n    92px 76px,\\n    88px 76px,\\n    88px 72px,\\n    84px 72px,\\n    84px 68px,\\n    80px 68px,\\n    80px 72px,\\n    76px 72px,\\n    76px 76px,\\n    72px 76px,\\n    72px 80px,\\n    64px 80px,\\n    64px 76px,\\n    60px 76px,\\n    60px 72px,\\n    56px 72px,\\n    56px 68px,\\n    52px 68px,\\n    52px 64px,\\n    48px 64px,\\n    48px 60px,\\n    44px 60px,\\n    44px 56px,\\n    40px 56px,\\n    40px 52px,\\n    36px 52px,\\n    36px 56px,\\n    32px 56px,\\n    32px 60px,\\n    28px 60px,\\n    28px 64px,\\n    24px 64px,\\n    24px 68px,\\n    20px 68px,\\n    20px 72px,\\n    16px 72px,\\n    16px 76px,\\n    12px 76px,\\n    12px 80px,\\n    0 80px,\\n    0 48px,\\n    4px 48px,\\n    4px 40px,\\n    8px 40px,\\n    8px 32px,\\n    12px 32px,\\n    12px 24px,\\n    16px 24px,\\n    16px 16px,\\n    12px 16px,\\n    12px 8px,\\n    8px 8px,\\n    8px 4px,\\n    4px 4px\\n  );\\n}\\n\\n.wing-dragon.right {\\n  --wing-shape: polygon(\\n    84px 0,\\n    96px 0,\\n    96px 4px,\\n    92px 4px,\\n    92px 8px,\\n    88px 8px,\\n    88px 16px,\\n    84px 16px,\\n    84px 24px,\\n    88px 24px,\\n    88px 32px,\\n    92px 32px,\\n    92px 40px,\\n    96px 40px,\\n    96px 48px,\\n    100px 48px,\\n    100px 80px,\\n    88px 80px,\\n    88px 76px,\\n    84px 76px,\\n    84px 72px,\\n    80px 72px,\\n    80px 68px,\\n    76px 68px,\\n    76px 64px,\\n    72px 64px,\\n    72px 60px,\\n    68px 60px,\\n    68px 56px,\\n    64px 56px,\\n    64px 52px,\\n    60px 52px,\\n    60px 56px,\\n    56px 56px,\\n    56px 60px,\\n    52px 60px,\\n    52px 64px,\\n    48px 64px,\\n    48px 68px,\\n    44px 68px,\\n    44px 72px,\\n    40px 72px,\\n    40px 76px,\\n    36px 76px,\\n    36px 80px,\\n    28px 80px,\\n    28px 76px,\\n    24px 76px,\\n    24px 72px,\\n    20px 72px,\\n    20px 68px,\\n    16px 68px,\\n    16px 72px,\\n    12px 72px,\\n    12px 76px,\\n    8px 76px,\\n    8px 80px,\\n    0 80px,\\n    0 20px,\\n    20px 20px,\\n    20px 16px,\\n    36px 16px,\\n    36px 12px,\\n    56px 12px,\\n    56px 8px,\\n    72px 8px,\\n    72px 4px,\\n    84px 4px\\n  );\\n}", "js": ""}' WHERE name = '龍翼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '龍翼', 'css', 'wings', 40, 'wings.svg', '{"html": "<div class=\\"wing-dragon left\\"><span></span></div>\\n<div class=\\"wing-dragon right\\"><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-dragon {\\n  --wing-color: #5a9a4a;\\n  top: calc(var(--wing-y, 10%) - 24px);\\n}\\n\\n.wing-dragon.left {\\n  left: calc(-104px + var(--wing-x, 0px));\\n}\\n\\n.wing-dragon.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 25 × 20 格：上緣是骨架往外伸，下緣三個大尖角 */\\n.wing-dragon {\\n  position: absolute;\\n  z-index: -2;\\n  width: 100px;\\n  height: 80px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-dragon span {\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-dragon.left {\\n  --wing-shape: polygon(\\n    4px 0,\\n    16px 0,\\n    16px 4px,\\n    28px 4px,\\n    28px 8px,\\n    44px 8px,\\n    44px 12px,\\n    64px 12px,\\n    64px 16px,\\n    80px 16px,\\n    80px 20px,\\n    100px 20px,\\n    100px 80px,\\n    92px 80px,\\n    92px 76px,\\n    88px 76px,\\n    88px 72px,\\n    84px 72px,\\n    84px 68px,\\n    80px 68px,\\n    80px 72px,\\n    76px 72px,\\n    76px 76px,\\n    72px 76px,\\n    72px 80px,\\n    64px 80px,\\n    64px 76px,\\n    60px 76px,\\n    60px 72px,\\n    56px 72px,\\n    56px 68px,\\n    52px 68px,\\n    52px 64px,\\n    48px 64px,\\n    48px 60px,\\n    44px 60px,\\n    44px 56px,\\n    40px 56px,\\n    40px 52px,\\n    36px 52px,\\n    36px 56px,\\n    32px 56px,\\n    32px 60px,\\n    28px 60px,\\n    28px 64px,\\n    24px 64px,\\n    24px 68px,\\n    20px 68px,\\n    20px 72px,\\n    16px 72px,\\n    16px 76px,\\n    12px 76px,\\n    12px 80px,\\n    0 80px,\\n    0 48px,\\n    4px 48px,\\n    4px 40px,\\n    8px 40px,\\n    8px 32px,\\n    12px 32px,\\n    12px 24px,\\n    16px 24px,\\n    16px 16px,\\n    12px 16px,\\n    12px 8px,\\n    8px 8px,\\n    8px 4px,\\n    4px 4px\\n  );\\n}\\n\\n.wing-dragon.right {\\n  --wing-shape: polygon(\\n    84px 0,\\n    96px 0,\\n    96px 4px,\\n    92px 4px,\\n    92px 8px,\\n    88px 8px,\\n    88px 16px,\\n    84px 16px,\\n    84px 24px,\\n    88px 24px,\\n    88px 32px,\\n    92px 32px,\\n    92px 40px,\\n    96px 40px,\\n    96px 48px,\\n    100px 48px,\\n    100px 80px,\\n    88px 80px,\\n    88px 76px,\\n    84px 76px,\\n    84px 72px,\\n    80px 72px,\\n    80px 68px,\\n    76px 68px,\\n    76px 64px,\\n    72px 64px,\\n    72px 60px,\\n    68px 60px,\\n    68px 56px,\\n    64px 56px,\\n    64px 52px,\\n    60px 52px,\\n    60px 56px,\\n    56px 56px,\\n    56px 60px,\\n    52px 60px,\\n    52px 64px,\\n    48px 64px,\\n    48px 68px,\\n    44px 68px,\\n    44px 72px,\\n    40px 72px,\\n    40px 76px,\\n    36px 76px,\\n    36px 80px,\\n    28px 80px,\\n    28px 76px,\\n    24px 76px,\\n    24px 72px,\\n    20px 72px,\\n    20px 68px,\\n    16px 68px,\\n    16px 72px,\\n    12px 72px,\\n    12px 76px,\\n    8px 76px,\\n    8px 80px,\\n    0 80px,\\n    0 20px,\\n    20px 20px,\\n    20px 16px,\\n    36px 16px,\\n    36px 12px,\\n    56px 12px,\\n    56px 8px,\\n    72px 8px,\\n    72px 4px,\\n    84px 4px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '龍翼');

-- wings：拍拍翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 45, starter_code = '{"html": "<div class=\\"wing-flap left\\"></div>\\n<div class=\\"wing-flap right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-flap {\\n  --wing-color: #6b8fb0;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing-flap.left {\\n  left: calc(-56px + var(--wing-x, 0px));\\n}\\n\\n.wing-flap.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 12 × 8 格；transform-origin 設在靠身體那一側，旋轉起來才像在拍 */\\n.wing-flap {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 32px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-flap::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n.wing-flap.left {\\n  transform-origin: right center;\\n  animation: wing-flap-left 0.5s ease-in-out infinite alternate;\\n}\\n\\n.wing-flap.right {\\n  transform-origin: left center;\\n  animation: wing-flap-right 0.5s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-flap-left {\\n  to {\\n    transform: rotate(25deg);\\n  }\\n}\\n\\n@keyframes wing-flap-right {\\n  to {\\n    transform: rotate(-25deg);\\n  }\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-flap.left {\\n  --wing-shape: polygon(\\n    16px 0,\\n    48px 0,\\n    48px 20px,\\n    44px 20px,\\n    44px 24px,\\n    40px 24px,\\n    40px 28px,\\n    32px 28px,\\n    32px 32px,\\n    0 32px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}\\n\\n.wing-flap.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    40px 4px,\\n    40px 8px,\\n    44px 8px,\\n    44px 12px,\\n    48px 12px,\\n    48px 32px,\\n    16px 32px,\\n    16px 28px,\\n    8px 28px,\\n    8px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px\\n  );\\n}", "js": ""}' WHERE name = '拍拍翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '拍拍翅膀', 'css', 'wings', 45, 'wings.svg', '{"html": "<div class=\\"wing-flap left\\"></div>\\n<div class=\\"wing-flap right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-flap {\\n  --wing-color: #6b8fb0;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing-flap.left {\\n  left: calc(-56px + var(--wing-x, 0px));\\n}\\n\\n.wing-flap.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 12 × 8 格；transform-origin 設在靠身體那一側，旋轉起來才像在拍 */\\n.wing-flap {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 32px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-flap::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n.wing-flap.left {\\n  transform-origin: right center;\\n  animation: wing-flap-left 0.5s ease-in-out infinite alternate;\\n}\\n\\n.wing-flap.right {\\n  transform-origin: left center;\\n  animation: wing-flap-right 0.5s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-flap-left {\\n  to {\\n    transform: rotate(25deg);\\n  }\\n}\\n\\n@keyframes wing-flap-right {\\n  to {\\n    transform: rotate(-25deg);\\n  }\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-flap.left {\\n  --wing-shape: polygon(\\n    16px 0,\\n    48px 0,\\n    48px 20px,\\n    44px 20px,\\n    44px 24px,\\n    40px 24px,\\n    40px 28px,\\n    32px 28px,\\n    32px 32px,\\n    0 32px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}\\n\\n.wing-flap.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    40px 4px,\\n    40px 8px,\\n    44px 8px,\\n    44px 12px,\\n    48px 12px,\\n    48px 32px,\\n    16px 32px,\\n    16px 28px,\\n    8px 28px,\\n    8px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '拍拍翅膀');

-- wings：會飛的翅膀
UPDATE parts SET category = 'js', slot = 'wings', price = 70, starter_code = '{"html": "<div class=\\"wing-fly left\\"></div>\\n<div class=\\"wing-fly right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-fly {\\n  --wing-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing-fly.left {\\n  left: calc(-56px + var(--wing-x, 0px));\\n}\\n\\n.wing-fly.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 12 × 8 格 */\\n.wing-fly {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 32px;\\n  cursor: pointer;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-fly::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n.wing-fly.left {\\n  transform-origin: right center;\\n}\\n\\n.wing-fly.right {\\n  transform-origin: left center;\\n}\\n\\n/* 飛的時候整隻上下飄、翅膀一直拍；JS 只負責加上、拿掉 flying */\\n.body.flying {\\n  animation: wing-float 1.2s ease-in-out infinite alternate;\\n}\\n\\n/* 飛的時候點身體還是要能跳：兩個動畫一起放，跳的時候疊在飄浮上面，跳完繼續飄 */\\n.body.flying.jump {\\n  animation:\\n    wing-float 1.2s ease-in-out infinite alternate,\\n    jump 0.4s ease-out;\\n}\\n\\n.body.flying .wing-fly {\\n  animation: wing-fly 0.3s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-float {\\n  to {\\n    translate: 0 -16px;\\n  }\\n}\\n\\n@keyframes wing-fly {\\n  to {\\n    scale: 1 0.6;\\n  }\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-fly.left {\\n  --wing-shape: polygon(\\n    16px 0,\\n    48px 0,\\n    48px 20px,\\n    44px 20px,\\n    44px 24px,\\n    40px 24px,\\n    40px 28px,\\n    32px 28px,\\n    32px 32px,\\n    0 32px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}\\n\\n.wing-fly.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    40px 4px,\\n    40px 8px,\\n    44px 8px,\\n    44px 12px,\\n    48px 12px,\\n    48px 32px,\\n    16px 32px,\\n    16px 28px,\\n    8px 28px,\\n    8px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px\\n  );\\n}", "js": "// 點翅膀讓整隻飄起來，再點一下停下來；飄和拍翅膀的動作寫在 CSS 的 .flying\\nconst flyBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.wing-fly\').forEach((wing) => {\\n  wing.addEventListener(\'click\', (event) => {\\n    // 翅膀長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    flyBody.classList.toggle(\'flying\')\\n  })\\n})"}' WHERE name = '會飛的翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會飛的翅膀', 'js', 'wings', 70, 'wings.svg', '{"html": "<div class=\\"wing-fly left\\"></div>\\n<div class=\\"wing-fly right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.wing-fly {\\n  --wing-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) + 4px);\\n}\\n\\n.wing-fly.left {\\n  left: calc(-56px + var(--wing-x, 0px));\\n}\\n\\n.wing-fly.right {\\n  left: calc(100% + 4px - var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 每片翅膀 12 × 8 格 */\\n.wing-fly {\\n  position: absolute;\\n  z-index: -2;\\n  width: 48px;\\n  height: 32px;\\n  cursor: pointer;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，外框就會跟著剪出來的形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.wing-fly::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--wing-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--wing-shape);\\n}\\n\\n.wing-fly.left {\\n  transform-origin: right center;\\n}\\n\\n.wing-fly.right {\\n  transform-origin: left center;\\n}\\n\\n/* 飛的時候整隻上下飄、翅膀一直拍；JS 只負責加上、拿掉 flying */\\n.body.flying {\\n  animation: wing-float 1.2s ease-in-out infinite alternate;\\n}\\n\\n/* 飛的時候點身體還是要能跳：兩個動畫一起放，跳的時候疊在飄浮上面，跳完繼續飄 */\\n.body.flying.jump {\\n  animation:\\n    wing-float 1.2s ease-in-out infinite alternate,\\n    jump 0.4s ease-out;\\n}\\n\\n.body.flying .wing-fly {\\n  animation: wing-fly 0.3s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-float {\\n  to {\\n    translate: 0 -16px;\\n  }\\n}\\n\\n@keyframes wing-fly {\\n  to {\\n    scale: 1 0.6;\\n  }\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角；右邊那片是左邊左右翻過來 */\\n.wing-fly.left {\\n  --wing-shape: polygon(\\n    16px 0,\\n    48px 0,\\n    48px 20px,\\n    44px 20px,\\n    44px 24px,\\n    40px 24px,\\n    40px 28px,\\n    32px 28px,\\n    32px 32px,\\n    0 32px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}\\n\\n.wing-fly.right {\\n  --wing-shape: polygon(\\n    0 0,\\n    32px 0,\\n    32px 4px,\\n    40px 4px,\\n    40px 8px,\\n    44px 8px,\\n    44px 12px,\\n    48px 12px,\\n    48px 32px,\\n    16px 32px,\\n    16px 28px,\\n    8px 28px,\\n    8px 24px,\\n    4px 24px,\\n    4px 20px,\\n    0 20px\\n  );\\n}", "js": "// 點翅膀讓整隻飄起來，再點一下停下來；飄和拍翅膀的動作寫在 CSS 的 .flying\\nconst flyBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.wing-fly\').forEach((wing) => {\\n  wing.addEventListener(\'click\', (event) => {\\n    // 翅膀長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    flyBody.classList.toggle(\'flying\')\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會飛的翅膀');

-- tail：會擺動的尾巴
UPDATE parts SET category = 'js', slot = 'tail', price = 60, starter_code = '{"html": "<div class=\\"tail\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail {\\n  --tail-color: #9a6440;\\n  top: var(--tail-y, 60%);\\n  left: 100%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 尾巴是一條 10 × 2 格的長條，尾巴尖往上翹一格 */\\n.tail {\\n  position: absolute;\\n  width: 40px;\\n  height: 8px;\\n  background: var(--tail-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 4px 0 rgb(255 255 255 / 35%);\\n  transform-origin: left center;\\n  cursor: pointer;\\n}\\n\\n/* 尾巴尖：沒有下框，往下蓋住長條的上框，兩塊才會連在一起 */\\n.tail::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  right: -4px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--tail-color);\\n  border: 4px solid #4a3426;\\n  border-bottom: 0;\\n}\\n\\n.tail.wag {\\n  animation: wag 0.4s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wag {\\n  from {\\n    transform: rotate(-20deg);\\n  }\\n  to {\\n    transform: rotate(20deg);\\n  }\\n}", "js": "// 點一下尾巴開始擺動，再點一下停下來\\nconst tail = document.querySelector(\\".tail\\");\\ntail.addEventListener(\\"click\\", (event) => {\\n  // 尾巴長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation();\\n  tail.classList.toggle(\\"wag\\");\\n});"}' WHERE name = '會擺動的尾巴';
