UPDATE parts SET category = 'css', slot = 'tail', price = 25, starter_code = '{"html": "<div class=\\"tail-fox\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-fox {\\n  --tail-color: #e8a33d;\\n  --tip-color: #fbf8f1;\\n  top: calc(var(--tail-y, 60%) - 24px);\\n  left: 100%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 尾巴 20 × 9 格，往右上翹；尾端白色是背景在 75% 的地方直接換顏色 */\\n.tail-fox {\\n  position: absolute;\\n  width: 80px;\\n  height: 36px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.tail-fox::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: linear-gradient(90deg, var(--tail-color) 75%, var(--tip-color) 75%);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--tail-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角 */\\n.tail-fox {\\n  --tail-shape: polygon(\\n    48px 0,\\n    64px 0,\\n    64px 4px,\\n    72px 4px,\\n    72px 20px,\\n    80px 20px,\\n    80px 24px,\\n    76px 24px,\\n    76px 28px,\\n    68px 28px,\\n    68px 32px,\\n    56px 32px,\\n    56px 36px,\\n    20px 36px,\\n    20px 32px,\\n    12px 32px,\\n    12px 28px,\\n    4px 28px,\\n    4px 24px,\\n    0 24px,\\n    0 20px,\\n    8px 20px,\\n    8px 16px,\\n    16px 16px,\\n    16px 12px,\\n    24px 12px,\\n    24px 8px,\\n    36px 8px,\\n    36px 4px,\\n    48px 4px\\n  );\\n}", "js": ""}' WHERE name = '狐狸尾巴';
