UPDATE parts SET category = 'html', slot = 'tail', price = 20, starter_code = '{"html": "<div class=\\"tail-devil\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-devil {\\n  --line-color: #4a3426;\\n  --arrow-color: #c8553d;\\n  top: calc(var(--tail-y, 60%) + 6px);\\n  left: calc(100% + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 細細的尾巴一階一階往上：元素本身是第一段，另外 3 段用 box-shadow 複製出來 */\\n.tail-devil {\\n  position: absolute;\\n  width: 12px;\\n  height: 4px;\\n  background: var(--line-color);\\n  box-shadow:\\n    12px -4px 0 var(--line-color),\\n    24px -8px 0 var(--line-color),\\n    36px -12px 0 var(--line-color);\\n}\\n\\n/* 尾端的箭頭：直的 3 格加上往右一格尖端 */\\n.tail-devil::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -16px;\\n  left: 48px;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--arrow-color);\\n  box-shadow:\\n    0 4px 0 var(--arrow-color),\\n    0 8px 0 var(--arrow-color),\\n    4px 4px 0 var(--arrow-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}", "js": ""}' WHERE name = '惡魔尾巴';
