-- tail：魚尾巴
UPDATE parts SET category = 'css', slot = 'tail', price = 20, starter_code = '{"html": "<div class=\\"tail-fish\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-fish {\\n  --tail-color: #6b8fb0;\\n  top: var(--tail-y, 60%);\\n  left: calc(100% + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 魚尾巴 6 塊：接身體的一塊、中間直的三塊、上下兩塊分岔；每一塊 2 × 2 格（8px） */\\n/* 元素本身是接身體那塊，另外 5 塊用 box-shadow 複製出來 */\\n.tail-fish {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--tail-color);\\n  box-shadow:\\n    8px -8px 0 var(--tail-color),\\n    8px 0 0 var(--tail-color),\\n    8px 8px 0 var(--tail-color),\\n    16px -16px 0 var(--tail-color),\\n    16px 16px 0 var(--tail-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}", "js": ""}' WHERE name = '魚尾巴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '魚尾巴', 'css', 'tail', 20, 'tail.svg', '{"html": "<div class=\\"tail-fish\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-fish {\\n  --tail-color: #6b8fb0;\\n  top: var(--tail-y, 60%);\\n  left: calc(100% + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 魚尾巴 6 塊：接身體的一塊、中間直的三塊、上下兩塊分岔；每一塊 2 × 2 格（8px） */\\n/* 元素本身是接身體那塊，另外 5 塊用 box-shadow 複製出來 */\\n.tail-fish {\\n  position: absolute;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--tail-color);\\n  box-shadow:\\n    8px -8px 0 var(--tail-color),\\n    8px 0 0 var(--tail-color),\\n    8px 8px 0 var(--tail-color),\\n    16px -16px 0 var(--tail-color),\\n    16px 16px 0 var(--tail-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '魚尾巴');

-- tail：閃電尾巴
UPDATE parts SET category = 'css', slot = 'tail', price = 25, starter_code = '{"html": "<div class=\\"tail-bolt\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-bolt {\\n  --tail-color: #f2d16b;\\n  top: calc(var(--tail-y, 60%) - 30px);\\n  left: calc(100% + 2px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 閃電 16 × 10 格，從身體往右上一折一折 */\\n.tail-bolt {\\n  position: absolute;\\n  width: 64px;\\n  height: 40px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.tail-bolt::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--tail-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--tail-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角 */\\n.tail-bolt {\\n  --tail-shape: polygon(\\n    48px 0,\\n    64px 0,\\n    64px 4px,\\n    56px 4px,\\n    56px 8px,\\n    48px 8px,\\n    48px 12px,\\n    56px 12px,\\n    56px 20px,\\n    48px 20px,\\n    48px 24px,\\n    40px 24px,\\n    40px 28px,\\n    32px 28px,\\n    32px 32px,\\n    24px 32px,\\n    24px 36px,\\n    16px 36px,\\n    16px 40px,\\n    0 40px,\\n    0 36px,\\n    8px 36px,\\n    8px 32px,\\n    16px 32px,\\n    16px 28px,\\n    24px 28px,\\n    24px 24px,\\n    32px 24px,\\n    32px 20px,\\n    40px 20px,\\n    40px 16px,\\n    24px 16px,\\n    24px 12px,\\n    32px 12px,\\n    32px 8px,\\n    40px 8px,\\n    40px 4px,\\n    48px 4px\\n  );\\n}", "js": ""}' WHERE name = '閃電尾巴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
