-- tail：恐龍尾巴
UPDATE parts SET category = 'css', slot = 'tail', price = 25, starter_code = '{"html": "<div class=\\"tail-dino\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.tail-dino {\\n  --tail-color: #5a9a4a;\\n  top: calc(var(--tail-y, 60%) - 18px);\\n  left: 100%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 尾巴 22 × 9 格，往外越來越細，上面三根背刺 */\\n.tail-dino {\\n  position: absolute;\\n  width: 88px;\\n  height: 36px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.tail-dino::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: var(--tail-color);\\n  box-shadow:\\n    inset 4px 4px 0 rgb(255 255 255 / 35%),\\n    inset -4px -4px 0 rgb(46 34 26 / 25%);\\n  clip-path: var(--tail-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角 */\\n.tail-dino {\\n  --tail-shape: polygon(\\n    12px 0,\\n    16px 0,\\n    16px 4px,\\n    20px 4px,\\n    20px 8px,\\n    32px 8px,\\n    32px 4px,\\n    36px 4px,\\n    36px 0,\\n    40px 0,\\n    40px 4px,\\n    44px 4px,\\n    44px 8px,\\n    56px 8px,\\n    56px 4px,\\n    60px 4px,\\n    60px 0,\\n    64px 0,\\n    64px 4px,\\n    68px 4px,\\n    68px 8px,\\n    88px 8px,\\n    88px 16px,\\n    80px 16px,\\n    80px 20px,\\n    68px 20px,\\n    68px 24px,\\n    52px 24px,\\n    52px 28px,\\n    32px 28px,\\n    32px 32px,\\n    16px 32px,\\n    16px 36px,\\n    0 36px,\\n    0 8px,\\n    8px 8px,\\n    8px 4px,\\n    12px 4px\\n  );\\n}", "js": ""}' WHERE name = '恐龍尾巴';
