-- feet：肉球腳掌
UPDATE parts SET category = 'html', slot = 'feet', price = 15, starter_code = '{"html": "<div class=\\"feet-paw left\\"></div>\\n<div class=\\"feet-paw right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-paw {\\n  --paw-color: #fbf8f1;\\n  --pad-color: #e8a0a0;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-paw.left {\\n  left: 11.67%;\\n}\\n\\n.feet-paw.right {\\n  right: 11.67%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 腳掌 5 × 3 格 */\\n.feet-paw {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 12px;\\n  background: var(--paw-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 底下的粉紅肉球 2 × 1 格 */\\n.feet-paw::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: 0;\\n  left: 6px;\\n  width: 8px;\\n  height: 4px;\\n  background: var(--pad-color);\\n}", "js": ""}' WHERE name = '肉球腳掌';
