-- feet：鴨蹼
UPDATE parts SET category = 'css', slot = 'feet', price = 15, starter_code = '{"html": "<div class=\\"feet-duck left\\"></div>\\n<div class=\\"feet-duck right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-duck {\\n  --foot-color: #e8a33d;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-duck.left {\\n  left: 22.5%;\\n}\\n\\n.feet-duck.right {\\n  right: 22.5%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 細細的腿 1 格寬、2 格長 */\\n.feet-duck {\\n  position: absolute;\\n  z-index: 1;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--foot-color);\\n}\\n\\n/* 蹼是 6 格：一排 4 格，最左、最右再往下各一格，看起來是張開的腳掌 */\\n/* 元素本身是左上那一格，另外 5 格用 box-shadow 複製出來 */\\n.feet-duck::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 8px;\\n  left: -6px;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--foot-color);\\n  box-shadow:\\n    4px 0 0 var(--foot-color),\\n    8px 0 0 var(--foot-color),\\n    12px 0 0 var(--foot-color),\\n    0 4px 0 var(--foot-color),\\n    12px 4px 0 var(--foot-color);\\n}", "js": ""}' WHERE name = '鴨蹼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '鴨蹼', 'css', 'feet', 15, 'feet.svg', '{"html": "<div class=\\"feet-duck left\\"></div>\\n<div class=\\"feet-duck right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-duck {\\n  --foot-color: #e8a33d;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-duck.left {\\n  left: 22.5%;\\n}\\n\\n.feet-duck.right {\\n  right: 22.5%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 細細的腿 1 格寬、2 格長 */\\n.feet-duck {\\n  position: absolute;\\n  z-index: 1;\\n  width: 4px;\\n  height: 8px;\\n  background: var(--foot-color);\\n}\\n\\n/* 蹼是 6 格：一排 4 格，最左、最右再往下各一格，看起來是張開的腳掌 */\\n/* 元素本身是左上那一格，另外 5 格用 box-shadow 複製出來 */\\n.feet-duck::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 8px;\\n  left: -6px;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--foot-color);\\n  box-shadow:\\n    4px 0 0 var(--foot-color),\\n    8px 0 0 var(--foot-color),\\n    12px 0 0 var(--foot-color),\\n    0 4px 0 var(--foot-color),\\n    12px 4px 0 var(--foot-color);\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '鴨蹼');

-- feet：馬蹄
UPDATE parts SET category = 'html', slot = 'feet', price = 20, starter_code = '{"html": "<div class=\\"feet-hoof left\\"><span class=\\"feet-hoof-tip\\"></span></div>\\n<div class=\\"feet-hoof right\\"><span class=\\"feet-hoof-tip\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-hoof {\\n  --leg-color: #c99a6b;\\n  --hoof-color: #2e221a;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-hoof.left {\\n  left: 18.33%;\\n}\\n\\n.feet-hoof.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 腿 4 格寬、5 格長 */\\n.feet-hoof {\\n  position: absolute;\\n  z-index: 1;\\n  width: 16px;\\n  height: 20px;\\n  background: var(--leg-color);\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 蹄比腿左右各寬一格，2 格高 */\\n.feet-hoof-tip {\\n  position: absolute;\\n  bottom: -8px;\\n  left: -4px;\\n  width: 24px;\\n  height: 8px;\\n  background: var(--hoof-color);\\n}", "js": ""}' WHERE name = '馬蹄';
