SELECT '馬蹄', 'html', 'feet', 20, 'feet.svg', '{"html": "<div class=\\"feet-hoof left\\"><span class=\\"feet-hoof-tip\\"></span></div>\\n<div class=\\"feet-hoof right\\"><span class=\\"feet-hoof-tip\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-hoof {\\n  --leg-color: #c99a6b;\\n  --hoof-color: #2e221a;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-hoof.left {\\n  left: 18.33%;\\n}\\n\\n.feet-hoof.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 腿 4 格寬、5 格長 */\\n.feet-hoof {\\n  position: absolute;\\n  z-index: 1;\\n  width: 16px;\\n  height: 20px;\\n  background: var(--leg-color);\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 20%);\\n}\\n\\n/* 蹄比腿左右各寬一格，2 格高 */\\n.feet-hoof-tip {\\n  position: absolute;\\n  bottom: -8px;\\n  left: -4px;\\n  width: 24px;\\n  height: 8px;\\n  background: var(--hoof-color);\\n}", "js": ""}'
