-- feet：章魚觸手
UPDATE parts SET category = 'css', slot = 'feet', price = 25, starter_code = '{"html": "<div class=\\"feet-octopus\\"><span></span><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-octopus {\\n  --tentacle-color: #e8a0a0;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 四條觸手平均排開，整排寬度是身體的 83%，身體變寬觸手會分開一點 */\\n.feet-octopus {\\n  position: absolute;\\n  z-index: 1;\\n  left: 8.5%;\\n  width: 83%;\\n  display: flex;\\n  justify-content: space-between;\\n}\\n\\n/* 每條觸手 2 格寬、5 格長，最底下往外勾一格 */\\n.feet-octopus span {\\n  position: relative;\\n  width: 8px;\\n  height: 20px;\\n  background: var(--tentacle-color);\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 15%);\\n}\\n\\n.feet-octopus span::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--tentacle-color);\\n}\\n\\n/* 左邊兩條往左勾、右邊兩條往右勾 */\\n.feet-octopus span:nth-child(-n + 2)::after {\\n  left: -4px;\\n}\\n\\n.feet-octopus span:nth-child(n + 3)::after {\\n  right: -4px;\\n}", "js": ""}' WHERE name = '章魚觸手';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '章魚觸手', 'css', 'feet', 25, 'feet.svg', '{"html": "<div class=\\"feet-octopus\\"><span></span><span></span><span></span><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-octopus {\\n  --tentacle-color: #e8a0a0;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 四條觸手平均排開，整排寬度是身體的 83%，身體變寬觸手會分開一點 */\\n.feet-octopus {\\n  position: absolute;\\n  z-index: 1;\\n  left: 8.5%;\\n  width: 83%;\\n  display: flex;\\n  justify-content: space-between;\\n}\\n\\n/* 每條觸手 2 格寬、5 格長，最底下往外勾一格 */\\n.feet-octopus span {\\n  position: relative;\\n  width: 8px;\\n  height: 20px;\\n  background: var(--tentacle-color);\\n  box-shadow: inset -4px 0 0 rgb(46 34 26 / 15%);\\n}\\n\\n.feet-octopus span::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: 0;\\n  width: 4px;\\n  height: 4px;\\n  background: var(--tentacle-color);\\n}\\n\\n/* 左邊兩條往左勾、右邊兩條往右勾 */\\n.feet-octopus span:nth-child(-n + 2)::after {\\n  left: -4px;\\n}\\n\\n.feet-octopus span:nth-child(n + 3)::after {\\n  right: -4px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '章魚觸手');

-- feet：輪子
UPDATE parts SET category = 'html', slot = 'feet', price = 25, starter_code = '{"html": "<div class=\\"feet-wheel-axle\\"></div>\\n<div class=\\"feet-wheel left\\"></div>\\n<div class=\\"feet-wheel right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-wheel {\\n  --tire-color: #2e221a;\\n  --hub-color: #a8a29a;\\n  top: calc(var(--leg-y, 100%) + 8px);\\n}\\n\\n.feet-wheel-axle {\\n  top: calc(var(--leg-y, 100%) + 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 輪軸是身體寬度的一半，兩個輪子裝在輪軸兩端 */\\n.feet-wheel-axle {\\n  position: absolute;\\n  z-index: 1;\\n  left: 25%;\\n  width: 50%;\\n  height: 4px;\\n  background: #4a3426;\\n}\\n\\n.feet-wheel.left {\\n  left: calc(25% - 10px);\\n}\\n\\n.feet-wheel.right {\\n  right: calc(25% - 10px);\\n}\\n\\n/* 輪子 5 × 5 格 */\\n.feet-wheel {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 20px;\\n  background: var(--tire-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 輪子中間的輪框 2 × 2 格 */\\n.feet-wheel::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 6px;\\n  left: 6px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--hub-color);\\n}", "js": ""}' WHERE name = '輪子';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '輪子', 'html', 'feet', 25, 'feet.svg', '{"html": "<div class=\\"feet-wheel-axle\\"></div>\\n<div class=\\"feet-wheel left\\"></div>\\n<div class=\\"feet-wheel right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-wheel {\\n  --tire-color: #2e221a;\\n  --hub-color: #a8a29a;\\n  top: calc(var(--leg-y, 100%) + 8px);\\n}\\n\\n.feet-wheel-axle {\\n  top: calc(var(--leg-y, 100%) + 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 輪軸是身體寬度的一半，兩個輪子裝在輪軸兩端 */\\n.feet-wheel-axle {\\n  position: absolute;\\n  z-index: 1;\\n  left: 25%;\\n  width: 50%;\\n  height: 4px;\\n  background: #4a3426;\\n}\\n\\n.feet-wheel.left {\\n  left: calc(25% - 10px);\\n}\\n\\n.feet-wheel.right {\\n  right: calc(25% - 10px);\\n}\\n\\n/* 輪子 5 × 5 格 */\\n.feet-wheel {\\n  position: absolute;\\n  z-index: 1;\\n  width: 20px;\\n  height: 20px;\\n  background: var(--tire-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 輪子中間的輪框 2 × 2 格 */\\n.feet-wheel::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 6px;\\n  left: 6px;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--hub-color);\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '輪子');

-- feet：彈簧腳
UPDATE parts SET category = 'css', slot = 'feet', price = 30, starter_code = '{"html": "<div class=\\"feet-spring left\\"></div>\\n<div class=\\"feet-spring right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-spring {\\n  --spring-color: #6f6a64;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-spring.left {\\n  left: 18.33%;\\n}\\n\\n.feet-spring.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 彈簧 4 格寬、7 格長：一格線、一格空一直重複，像一圈一圈的彈簧 */\\n.feet-spring {\\n  position: absolute;\\n  z-index: 1;\\n  width: 16px;\\n  height: 28px;\\n  background: repeating-linear-gradient(\\n    var(--spring-color) 0 4px,\\n    transparent 4px 8px\\n  );\\n}\\n\\n/* 底下的腳墊，比彈簧左右各寬一格 */\\n.feet-spring::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: -4px;\\n  left: -4px;\\n  width: 24px;\\n  height: 4px;\\n  background: #4a3426;\\n}", "js": ""}' WHERE name = '彈簧腳';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '彈簧腳', 'css', 'feet', 30, 'feet.svg', '{"html": "<div class=\\"feet-spring left\\"></div>\\n<div class=\\"feet-spring right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-spring {\\n  --spring-color: #6f6a64;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-spring.left {\\n  left: 18.33%;\\n}\\n\\n.feet-spring.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 彈簧 4 格寬、7 格長：一格線、一格空一直重複，像一圈一圈的彈簧 */\\n.feet-spring {\\n  position: absolute;\\n  z-index: 1;\\n  width: 16px;\\n  height: 28px;\\n  background: repeating-linear-gradient(\\n    var(--spring-color) 0 4px,\\n    transparent 4px 8px\\n  );\\n}\\n\\n/* 底下的腳墊，比彈簧左右各寬一格 */\\n.feet-spring::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: -4px;\\n  left: -4px;\\n  width: 24px;\\n  height: 4px;\\n  background: #4a3426;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '彈簧腳');

-- feet：會走路的腳
UPDATE parts SET category = 'js', slot = 'feet', price = 60, starter_code = '{"html": "<div class=\\"feet-walk left\\"></div>\\n<div class=\\"feet-walk right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-walk {\\n  --foot-color: #9a6440;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-walk.left {\\n  left: 18.33%;\\n}\\n\\n.feet-walk.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻腳 3 × 4 格，加上 4px 的深棕外框 */\\n.feet-walk {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 16px;\\n  background: var(--foot-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 25%);\\n  cursor: pointer;\\n}\\n\\n/* 走路時兩隻腳輪流抬起來，右腳晚半拍；一次抬兩格，一格一格動；JS 只負責加上、拿掉 walking */\\n.body.walking .feet-walk {\\n  animation: feet-step 0.6s steps(2) infinite;\\n}\\n\\n.body.walking .feet-walk.right {\\n  animation-delay: 0.3s;\\n}\\n\\n@keyframes feet-step {\\n  50% {\\n    translate: 0 -8px;\\n  }\\n}", "js": "// 點腳開始左右交替踏步，再點一下停下來；踏步的動作寫在 CSS 的 .walking\\nconst walkBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.feet-walk\').forEach((foot) => {\\n  foot.addEventListener(\'click\', (event) => {\\n    // 腳長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    walkBody.classList.toggle(\'walking\')\\n  })\\n})"}' WHERE name = '會走路的腳';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會走路的腳', 'js', 'feet', 60, 'feet.svg', '{"html": "<div class=\\"feet-walk left\\"></div>\\n<div class=\\"feet-walk right\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.feet-walk {\\n  --foot-color: #9a6440;\\n  top: calc(var(--leg-y, 100%) + 4px);\\n}\\n\\n.feet-walk.left {\\n  left: 18.33%;\\n}\\n\\n.feet-walk.right {\\n  right: 18.33%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 一隻腳 3 × 4 格，加上 4px 的深棕外框 */\\n.feet-walk {\\n  position: absolute;\\n  z-index: 1;\\n  width: 12px;\\n  height: 16px;\\n  background: var(--foot-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 25%);\\n  cursor: pointer;\\n}\\n\\n/* 走路時兩隻腳輪流抬起來，右腳晚半拍；一次抬兩格，一格一格動；JS 只負責加上、拿掉 walking */\\n.body.walking .feet-walk {\\n  animation: feet-step 0.6s steps(2) infinite;\\n}\\n\\n.body.walking .feet-walk.right {\\n  animation-delay: 0.3s;\\n}\\n\\n@keyframes feet-step {\\n  50% {\\n    translate: 0 -8px;\\n  }\\n}", "js": "// 點腳開始左右交替踏步，再點一下停下來；踏步的動作寫在 CSS 的 .walking\\nconst walkBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.feet-walk\').forEach((foot) => {\\n  foot.addEventListener(\'click\', (event) => {\\n    // 腳長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    walkBody.classList.toggle(\'walking\')\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會走路的腳');

-- accessory：領結
UPDATE parts SET category = 'html', slot = 'accessory', price = 10, starter_code = '{"html": "<div class=\\"accessory-bowtie\\"><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-bowtie {\\n  --bow-color: #c8553d;\\n  top: calc(var(--neck-y, 80%) - 8px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 領結寬度是身體的 40%，身體變寬也跟著變寬；左右兩塊是蝴蝶結的兩邊，中間的 span 是結 */\\n.accessory-bowtie {\\n  position: absolute;\\n  left: 30%;\\n  width: 40%;\\n  height: 24px;\\n}\\n\\n/* box-sizing: border-box 讓寬度把外框也算進去，兩塊各占一半剛好排滿 */\\n.accessory-bowtie::before,\\n.accessory-bowtie::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  box-sizing: border-box;\\n  width: 50%;\\n  height: 24px;\\n  background: var(--bow-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 20%);\\n}\\n\\n.accessory-bowtie::before {\\n  left: 0;\\n}\\n\\n.accessory-bowtie::after {\\n  right: 0;\\n}\\n\\n/* 中間的結 2 × 2 格，疊在兩塊上面；兩邊比中間高，看起來就是蝴蝶結 */\\n.accessory-bowtie span {\\n  position: absolute;\\n  z-index: 1;\\n  top: 4px;\\n  left: calc(50% - 8px);\\n  width: 8px;\\n  height: 8px;\\n  background: var(--bow-color);\\n  border: 4px solid #4a3426;\\n}", "js": ""}' WHERE name = '領結';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '領結', 'html', 'accessory', 10, 'accessory.svg', '{"html": "<div class=\\"accessory-bowtie\\"><span></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-bowtie {\\n  --bow-color: #c8553d;\\n  top: calc(var(--neck-y, 80%) - 8px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 領結寬度是身體的 40%，身體變寬也跟著變寬；左右兩塊是蝴蝶結的兩邊，中間的 span 是結 */\\n.accessory-bowtie {\\n  position: absolute;\\n  left: 30%;\\n  width: 40%;\\n  height: 24px;\\n}\\n\\n/* box-sizing: border-box 讓寬度把外框也算進去，兩塊各占一半剛好排滿 */\\n.accessory-bowtie::before,\\n.accessory-bowtie::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 0;\\n  box-sizing: border-box;\\n  width: 50%;\\n  height: 24px;\\n  background: var(--bow-color);\\n  border: 4px solid #4a3426;\\n  box-shadow: inset 0 -4px 0 rgb(46 34 26 / 20%);\\n}\\n\\n.accessory-bowtie::before {\\n  left: 0;\\n}\\n\\n.accessory-bowtie::after {\\n  right: 0;\\n}\\n\\n/* 中間的結 2 × 2 格，疊在兩塊上面；兩邊比中間高，看起來就是蝴蝶結 */\\n.accessory-bowtie span {\\n  position: absolute;\\n  z-index: 1;\\n  top: 4px;\\n  left: calc(50% - 8px);\\n  width: 8px;\\n  height: 8px;\\n  background: var(--bow-color);\\n  border: 4px solid #4a3426;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '領結');

-- accessory：圍巾
UPDATE parts SET category = 'css', slot = 'accessory', price = 15, starter_code = '{"html": "<div class=\\"accessory-scarf\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-scarf {\\n  --scarf-color: #5a9a4a;\\n  --stripe-color: #fbf8f1;\\n  top: calc(var(--neck-y, 80%) + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 橫的一條繞在身體上，寬度是身體加一圈；條紋是 2 格綠、1 格白一直重複 */\\n.accessory-scarf {\\n  position: absolute;\\n  left: -4px;\\n  width: calc(100% + 8px);\\n  height: 8px;\\n  background: repeating-linear-gradient(\\n    90deg,\\n    var(--scarf-color) 0 8px,\\n    var(--stripe-color) 8px 12px\\n  );\\n  border-top: 4px solid #4a3426;\\n  border-bottom: 4px solid #4a3426;\\n}\\n\\n/* 垂下來的那一端：3 格寬、8 格長，條紋改成橫的 */\\n.accessory-scarf::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 8px;\\n  right: 16px;\\n  width: 12px;\\n  height: 32px;\\n  background: repeating-linear-gradient(\\n    var(--scarf-color) 0 8px,\\n    var(--stripe-color) 8px 12px\\n  );\\n  border: 4px solid #4a3426;\\n}", "js": ""}' WHERE name = '圍巾';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '圍巾', 'css', 'accessory', 15, 'accessory.svg', '{"html": "<div class=\\"accessory-scarf\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-scarf {\\n  --scarf-color: #5a9a4a;\\n  --stripe-color: #fbf8f1;\\n  top: calc(var(--neck-y, 80%) + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 橫的一條繞在身體上，寬度是身體加一圈；條紋是 2 格綠、1 格白一直重複 */\\n.accessory-scarf {\\n  position: absolute;\\n  left: -4px;\\n  width: calc(100% + 8px);\\n  height: 8px;\\n  background: repeating-linear-gradient(\\n    90deg,\\n    var(--scarf-color) 0 8px,\\n    var(--stripe-color) 8px 12px\\n  );\\n  border-top: 4px solid #4a3426;\\n  border-bottom: 4px solid #4a3426;\\n}\\n\\n/* 垂下來的那一端：3 格寬、8 格長，條紋改成橫的 */\\n.accessory-scarf::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 8px;\\n  right: 16px;\\n  width: 12px;\\n  height: 32px;\\n  background: repeating-linear-gradient(\\n    var(--scarf-color) 0 8px,\\n    var(--stripe-color) 8px 12px\\n  );\\n  border: 4px solid #4a3426;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '圍巾');

-- accessory：項鍊
UPDATE parts SET category = 'html', slot = 'accessory', price = 15, starter_code = '{"html": "<div class=\\"accessory-necklace\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-necklace {\\n  --bead-color: #fbf8f1;\\n  --pendant-color: #e8a33d;\\n  top: calc(var(--neck-y, 80%) - 16px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 虛線邊框剛好是一顆一顆方方的珠子，寬度是身體的 53%，跟著身體變寬 */\\n.accessory-necklace {\\n  position: absolute;\\n  left: calc(23.5% - 4px);\\n  width: 53%;\\n  height: 12px;\\n  border: 4px dashed var(--bead-color);\\n  border-top: none;\\n}\\n\\n/* 墜子 2 × 2 格，掛在正中間 */\\n.accessory-necklace::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: -12px;\\n  left: calc(50% - 8px);\\n  width: 8px;\\n  height: 8px;\\n  background: var(--pendant-color);\\n  border: 4px solid #4a3426;\\n}", "js": ""}' WHERE name = '項鍊';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
