FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '項鍊');

-- accessory：小花
UPDATE parts SET category = 'html', slot = 'accessory', price = 15, starter_code = '{"html": "<div class=\\"accessory-flower\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-flower {\\n  --center-color: #f2d16b;\\n  --petal-color: #e8a0a0;\\n  top: calc(var(--horn-y, 0%) + 6px);\\n  left: calc(50% + 34px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 中間是花心，上下左右四片花瓣用 box-shadow 複製出來；每一塊 2 × 2 格（8px） */\\n.accessory-flower {\\n  position: absolute;\\n  z-index: 1;\\n  width: 8px;\\n  height: 8px;\\n  background: var(--center-color);\\n  box-shadow:\\n    0 -8px 0 var(--petal-color),\\n    8px 0 0 var(--petal-color),\\n    0 8px 0 var(--petal-color),\\n    -8px 0 0 var(--petal-color);\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}", "js": ""}' WHERE name = '小花';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
