FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '小花');

-- accessory：勳章
UPDATE parts SET category = 'html', slot = 'accessory', price = 20, starter_code = '{"html": "<div class=\\"accessory-medal\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-medal {\\n  --medal-color: #f2d16b;\\n  --ribbon-color: #6b8fb0;\\n  top: calc(var(--neck-y, 80%) - 14px);\\n  left: 5%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 掛在胸口左邊，大小是身體寬度的 17%，用 aspect-ratio 保持方方正正 */\\n.accessory-medal {\\n  position: absolute;\\n  width: 17%;\\n  aspect-ratio: 1;\\n  background: var(--medal-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 上面的緞帶 2 × 3 格 */\\n.accessory-medal::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -16px;\\n  left: calc(50% - 4px);\\n  width: 8px;\\n  height: 12px;\\n  background: var(--ribbon-color);\\n}\\n\\n/* 左上角一格白色反光 */\\n.accessory-medal::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}' WHERE name = '勳章';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '勳章', 'html', 'accessory', 20, 'accessory.svg', '{"html": "<div class=\\"accessory-medal\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-medal {\\n  --medal-color: #f2d16b;\\n  --ribbon-color: #6b8fb0;\\n  top: calc(var(--neck-y, 80%) - 14px);\\n  left: 5%;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 掛在胸口左邊，大小是身體寬度的 17%，用 aspect-ratio 保持方方正正 */\\n.accessory-medal {\\n  position: absolute;\\n  width: 17%;\\n  aspect-ratio: 1;\\n  background: var(--medal-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n}\\n\\n/* 上面的緞帶 2 × 3 格 */\\n.accessory-medal::before {\\n  content: \'\';\\n  position: absolute;\\n  top: -16px;\\n  left: calc(50% - 4px);\\n  width: 8px;\\n  height: 12px;\\n  background: var(--ribbon-color);\\n}\\n\\n/* 左上角一格白色反光 */\\n.accessory-medal::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '勳章');

-- accessory：背包
UPDATE parts SET category = 'html', slot = 'accessory', price = 20, starter_code = '{"html": "<div class=\\"accessory-backpack\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-backpack {\\n  --bag-color: #6b8fb0;\\n  top: calc(var(--wing-y, 10%) + 10px);\\n  left: calc(-28px + var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 只畫露在身體左邊的那一截 6 × 13 格，右邊貼著身體的框 */\\n.accessory-backpack {\\n  position: absolute;\\n  width: 24px;\\n  height: 52px;\\n  background: var(--bag-color);\\n  border: 4px solid #4a3426;\\n  border-right: none;\\n  box-shadow: inset 4px 4px 0 rgb(255 255 255 / 30%);\\n}\\n\\n/* 外面的口袋 3 × 3 格 */\\n.accessory-backpack::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 24px;\\n  left: 4px;\\n  width: 12px;\\n  height: 12px;\\n  background: rgb(46 34 26 / 20%);\\n  border: 4px solid #4a3426;\\n}", "js": ""}' WHERE name = '背包';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '背包', 'html', 'accessory', 20, 'accessory.svg', '{"html": "<div class=\\"accessory-backpack\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-backpack {\\n  --bag-color: #6b8fb0;\\n  top: calc(var(--wing-y, 10%) + 10px);\\n  left: calc(-28px + var(--wing-x, 0px));\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 只畫露在身體左邊的那一截 6 × 13 格，右邊貼著身體的框 */\\n.accessory-backpack {\\n  position: absolute;\\n  width: 24px;\\n  height: 52px;\\n  background: var(--bag-color);\\n  border: 4px solid #4a3426;\\n  border-right: none;\\n  box-shadow: inset 4px 4px 0 rgb(255 255 255 / 30%);\\n}\\n\\n/* 外面的口袋 3 × 3 格 */\\n.accessory-backpack::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 24px;\\n  left: 4px;\\n  width: 12px;\\n  height: 12px;\\n  background: rgb(46 34 26 / 20%);\\n  border: 4px solid #4a3426;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '背包');

-- accessory：披風
UPDATE parts SET category = 'css', slot = 'accessory', price = 25, starter_code = '{"html": "<div class=\\"accessory-cape\\"></div>", "css": "/* 想換顏色，改這裡就好 */\\n.accessory-cape {\\n  --cape-color: #c8553d;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 披風是一塊從肩膀往下張開的梯形，z-index: -2 排在身體後面，中間自然被身體蓋住，不用挖洞 */\\n/* 圓的、蛋形的身體也不會露白，跳的時候跟著身體一起動 */\\n.accessory-cape {\\n  position: absolute;\\n  z-index: -2;\\n  top: 63%;\\n  left: -16px;\\n  width: calc(100% + 32px);\\n  height: calc(37% + 16px);\\n  background: var(--cape-color);\\n  clip-path: var(--cape-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，左右兩邊每往下一段就往外一格，一階一階張開 */\\n.accessory-cape {\\n  --cape-shape: polygon(\\n    12px 0,\\n    calc(100% - 12px) 0,\\n    calc(100% - 12px) 25%,\\n    calc(100% - 8px) 25%,\\n    calc(100% - 8px) 50%,\\n    calc(100% - 4px) 50%,\\n    calc(100% - 4px) 75%,\\n    100% 75%,\\n    100% 100%,\\n    0 100%,\\n    0 75%,\\n    4px 75%,\\n    4px 50%,\\n    8px 50%,\\n    8px 25%,\\n    12px 25%\\n  );\\n}", "js": ""}' WHERE name = '披風';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '披風', 'css', 'accessory', 25, 'accessory.svg', '{"html": "<div class=\\"accessory-cape\\"></div>", "css": "/* 想換顏色，改這裡就好 */\\n.accessory-cape {\\n  --cape-color: #c8553d;\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 披風是一塊從肩膀往下張開的梯形，z-index: -2 排在身體後面，中間自然被身體蓋住，不用挖洞 */\\n/* 圓的、蛋形的身體也不會露白，跳的時候跟著身體一起動 */\\n.accessory-cape {\\n  position: absolute;\\n  z-index: -2;\\n  top: 63%;\\n  left: -16px;\\n  width: calc(100% + 32px);\\n  height: calc(37% + 16px);\\n  background: var(--cape-color);\\n  clip-path: var(--cape-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，左右兩邊每往下一段就往外一格，一階一階張開 */\\n.accessory-cape {\\n  --cape-shape: polygon(\\n    12px 0,\\n    calc(100% - 12px) 0,\\n    calc(100% - 12px) 25%,\\n    calc(100% - 8px) 25%,\\n    calc(100% - 8px) 50%,\\n    calc(100% - 4px) 50%,\\n    calc(100% - 4px) 75%,\\n    100% 75%,\\n    100% 100%,\\n    0 100%,\\n    0 75%,\\n    4px 75%,\\n    4px 50%,\\n    8px 50%,\\n    8px 25%,\\n    12px 25%\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '披風');

-- accessory：小雨傘
UPDATE parts SET category = 'html', slot = 'accessory', price = 25, starter_code = '{"html": "<div class=\\"accessory-umbrella\\"><span class=\\"accessory-umbrella-top\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-umbrella {\\n  --canopy-color: #c8553d;\\n  --stripe-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) - 32px);\\n  left: calc(100% + 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 本體是 1 格寬、14 格長的傘柄，最下面往左勾一格 */\\n.accessory-umbrella {\\n  position: absolute;\\n  width: 4px;\\n  height: 56px;\\n  background: #4a3426;\\n}\\n\\n.accessory-umbrella::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: 0;\\n  left: -4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #4a3426;\\n}\\n\\n/* 傘面 14 × 5 格，紅白直條紋；外框跟著剪出來的圓頂走 */\\n.accessory-umbrella-top {\\n  position: absolute;\\n  top: -20px;\\n  left: -26px;\\n  width: 56px;\\n  height: 20px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.accessory-umbrella-top::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: repeating-linear-gradient(\\n    90deg,\\n    var(--canopy-color) 0 8px,\\n    var(--stripe-color) 8px 16px\\n  );\\n  clip-path: var(--canopy-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角，左右兩邊一階一階收成圓頂 */\\n.accessory-umbrella-top {\\n  --canopy-shape: polygon(\\n    16px 0,\\n    40px 0,\\n    40px 4px,\\n    48px 4px,\\n    48px 8px,\\n    52px 8px,\\n    52px 12px,\\n    56px 12px,\\n    56px 20px,\\n    0 20px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}", "js": ""}' WHERE name = '小雨傘';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '小雨傘', 'html', 'accessory', 25, 'accessory.svg', '{"html": "<div class=\\"accessory-umbrella\\"><span class=\\"accessory-umbrella-top\\"></span></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-umbrella {\\n  --canopy-color: #c8553d;\\n  --stripe-color: #fbf8f1;\\n  top: calc(var(--wing-y, 10%) - 32px);\\n  left: calc(100% + 14px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 本體是 1 格寬、14 格長的傘柄，最下面往左勾一格 */\\n.accessory-umbrella {\\n  position: absolute;\\n  width: 4px;\\n  height: 56px;\\n  background: #4a3426;\\n}\\n\\n.accessory-umbrella::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: 0;\\n  left: -4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #4a3426;\\n}\\n\\n/* 傘面 14 × 5 格，紅白直條紋；外框跟著剪出來的圓頂走 */\\n.accessory-umbrella-top {\\n  position: absolute;\\n  top: -20px;\\n  left: -26px;\\n  width: 56px;\\n  height: 20px;\\n  /* 外框用 drop-shadow 往上下左右各畫一次 4px，會沿著形狀走 */\\n  filter:\\n    drop-shadow(4px 0 0 #4a3426)\\n    drop-shadow(-4px 0 0 #4a3426)\\n    drop-shadow(0 4px 0 #4a3426)\\n    drop-shadow(0 -4px 0 #4a3426);\\n}\\n\\n.accessory-umbrella-top::before {\\n  content: \'\';\\n  position: absolute;\\n  inset: 0;\\n  background: repeating-linear-gradient(\\n    90deg,\\n    var(--canopy-color) 0 8px,\\n    var(--stripe-color) 8px 16px\\n  );\\n  clip-path: var(--canopy-shape);\\n}\\n\\n/* 下面是剪出形狀的程式，想改形狀再研究 */\\n/* 從左上開始順時針走一圈，每一行是一個轉角，左右兩邊一階一階收成圓頂 */\\n.accessory-umbrella-top {\\n  --canopy-shape: polygon(\\n    16px 0,\\n    40px 0,\\n    40px 4px,\\n    48px 4px,\\n    48px 8px,\\n    52px 8px,\\n    52px 12px,\\n    56px 12px,\\n    56px 20px,\\n    0 20px,\\n    0 12px,\\n    4px 12px,\\n    4px 8px,\\n    8px 8px,\\n    8px 4px,\\n    16px 4px\\n  );\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '小雨傘');

-- accessory：會飄的氣球
UPDATE parts SET category = 'js', slot = 'accessory', price = 60, starter_code = '{"html": "<div class=\\"accessory-balloon\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-balloon {\\n  --balloon-color: #c8553d;\\n  top: calc(var(--wing-y, 10%) - 60px);\\n  left: calc(100% + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 氣球 6 × 7 格 */\\n.accessory-balloon {\\n  position: absolute;\\n  width: 24px;\\n  height: 28px;\\n  background: var(--balloon-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n  cursor: pointer;\\n}\\n\\n/* 左上角一格白色反光 */\\n.accessory-balloon::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}\\n\\n/* 綁在身體上的線，1 格寬 */\\n.accessory-balloon::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 32px;\\n  left: 10px;\\n  width: 4px;\\n  height: 60px;\\n  background: #4a3426;\\n}\\n\\n/* 飄上去再慢慢回來；JS 只負責加上 rising */\\n.accessory-balloon.rising {\\n  animation: balloon-rise 2.4s ease-in-out;\\n}\\n\\n@keyframes balloon-rise {\\n  30% {\\n    translate: 0 -60px;\\n  }\\n}", "js": "// 點氣球讓它飄上去，再慢慢回到原本的位置；飄的動作寫在 CSS 的 .rising\\nconst balloon = document.querySelector(\'.accessory-balloon\')\\nballoon.addEventListener(\'click\', (event) => {\\n  // 氣球長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  balloon.classList.add(\'rising\')\\n})\\n\\n// 動畫播完把 class 拿掉，下次才能再飄\\n// 擋住不往上傳，不然身體收到 animationend 會把自己的 jump 也拿掉\\nballoon.addEventListener(\'animationend\', (event) => {\\n  event.stopPropagation()\\n  balloon.classList.remove(\'rising\')\\n})"}' WHERE name = '會飄的氣球';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會飄的氣球', 'js', 'accessory', 60, 'accessory.svg', '{"html": "<div class=\\"accessory-balloon\\"></div>", "css": "/* 想換顏色、移位置，改這裡就好 */\\n.accessory-balloon {\\n  --balloon-color: #c8553d;\\n  top: calc(var(--wing-y, 10%) - 60px);\\n  left: calc(100% + 4px);\\n}\\n\\n/* ===== 零件形狀 ===== */\\n\\n/* 氣球 6 × 7 格 */\\n.accessory-balloon {\\n  position: absolute;\\n  width: 24px;\\n  height: 28px;\\n  background: var(--balloon-color);\\n  /* 外框用 box-shadow 往上下左右各複製一次深棕色，四個角空出來，看起來就是像素風的圓 */\\n  box-shadow:\\n    0 -4px 0 #4a3426,\\n    0 4px 0 #4a3426,\\n    -4px 0 0 #4a3426,\\n    4px 0 0 #4a3426;\\n  cursor: pointer;\\n}\\n\\n/* 左上角一格白色反光 */\\n.accessory-balloon::before {\\n  content: \'\';\\n  position: absolute;\\n  top: 4px;\\n  left: 4px;\\n  width: 4px;\\n  height: 4px;\\n  background: #fbf8f1;\\n}\\n\\n/* 綁在身體上的線，1 格寬 */\\n.accessory-balloon::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 32px;\\n  left: 10px;\\n  width: 4px;\\n  height: 60px;\\n  background: #4a3426;\\n}\\n\\n/* 飄上去再慢慢回來；JS 只負責加上 rising */\\n.accessory-balloon.rising {\\n  animation: balloon-rise 2.4s ease-in-out;\\n}\\n\\n@keyframes balloon-rise {\\n  30% {\\n    translate: 0 -60px;\\n  }\\n}", "js": "// 點氣球讓它飄上去，再慢慢回到原本的位置；飄的動作寫在 CSS 的 .rising\\nconst balloon = document.querySelector(\'.accessory-balloon\')\\nballoon.addEventListener(\'click\', (event) => {\\n  // 氣球長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  balloon.classList.add(\'rising\')\\n})\\n\\n// 動畫播完把 class 拿掉，下次才能再飄\\n// 擋住不往上傳，不然身體收到 animationend 會把自己的 jump 也拿掉\\nballoon.addEventListener(\'animationend\', (event) => {\\n  event.stopPropagation()\\n  balloon.classList.remove(\'rising\')\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會飄的氣球');

SELECT slot, COUNT(*) AS parts FROM parts GROUP BY slot;
